NAME = 'ACV: A Conservative Version'
BOOK = 'I Samuel'

CHAPTERS = {
    1: {
        1: 'Bil je mož iz Ramataim-zofima, z Efraimskega gorovja, ki mu je bilo ime Elkana, sin Jerohama, sina Elihuja, sina Tohuja, sina Zufovega, Efraimec.',
        2: 'In imel je dve ženi, eni je bilo ime Ana, drugi pa Penina; in Penina je imela otroke, Ana pa ni imela otrok.',
        3: 'In ta mož je hodil vsako leto gori iz mesta svojega, da bi molil in daroval Gospodu nad vojskami v Silu. Ondi sta bila duhovnika Gospodu dva sinova Elijeva, Ofni in Pinehas.',
        4: 'In kadar je prišel dan, da je Elkana daroval, je dal deleže Penini, ženi svoji, in vsem sinovom in hčeram njenim.',
        5: 'Ali Ani je dal dvojen delež, ker Ano je ljubil, a Gospod ji je zaprl maternico.',
        6: 'In njena soporočenka jo je hudo žalila, da bi jo ujezila, ker ji je bil Gospod zaprl maternico.',
        7: 'In ker je delal tisto vsako leto, kadarkoli je šla v hišo Gospodovo, jo je tako žalila; in Ana je plakala in ni ničesar jedla.',
        8: 'In Elkana, njen mož, ji reče: Ana, zakaj plačeš? in zakaj ne ješ? in zakaj ti je srce žalostno? Nisem li jaz boljši tebi nego deset sinov?',
        9: 'In vstala je Ana, potem ko so jedli in pili v Silu. In Eli duhovnik je sedel na stolu svojem pri podboju Gospodovega templja.',
        10: 'In njej je bilo bridko v duši, in molila je h Gospodu in silno jokala.',
        11: 'In stori obljubo in reče: O Gospod nad vojskami, ako se milo ozreš na ponižanje dekle svoje in se me spomniš in ne pozabiš dekle svoje, a daš dekli svoji moški zarod, tedaj ga posvetim Gospodu za vse žive dni njegove, in britev naj ne pride na glavo njegovo.',
        12: 'In ko je dolgo molila pred Gospodom, je Eli pazil na usta njena.',
        13: 'Ana namreč je govorila v srcu svojem, le njena ustnica se je gibala, toda glasu njenega ni bilo slišati. Zato je Eli menil, da je vinjena.',
        14: 'In ji reče Eli: Doklej boš pijana? Iztrezni se od vina svojega!',
        15: 'Ana pa odgovori ter reče: Nikar, gospod moj, žena sem otožnega duha; vina in močne pijače nisem pila, temuč srce svoje sem izlila pred Gospodom.',
        16: 'Ne rači šteti dekle svoje za hčer Belijalovo, zakaj od velikega žalovanja in razžaljenja sem doslej govorila.',
        17: 'Eliji odgovori in veli: Pojdi v miru! Bog Izraelov naj ti izpolni prošnjo, ki si jo prosila.',
        18: 'Ona reče: Naj najde dekla tvoja milost v očeh tvojih! Nato je žena šla svojim potem, in je jedla in lice ji ni bilo več žalostno.',
        19: 'In zgodaj zjutraj vstanejo, in ko se poklonijo pred Gospodom, se napotijo nazaj in pridejo v hišo svojo v Rami. In Elkana spozna Ano, ženo svojo, in Gospod se je spomni.',
        20: 'In ko preteče čas, potem ko je Ana spočela, je rodila sina in ga imenovala Samuela, kajti „izprosila sem ga od Gospoda “.',
        21: 'In ko je šel mož Elkana in vsa družina njegova, da prinese Gospodu vsakoletno daritev in obljubo svojo,',
        22: 'ni šla Ana ž njim, zakaj rekla je možu svojemu: Pojdem šele, ko bo deček odstavljen, potem ga popeljem, da se pokaže pred obličjem Gospodovim in ostane ondi vekomaj.',
        23: 'Elkana, mož njen, ji reče: Stóri, kakor se ti dobro vidi; ostani, dokler ga ne odstaviš! Samo da Gospod potrdi besedo svojo! In žena je ostala doma in dojila sina, dokler ga ni odstavila.',
        24: 'In ko ga je odstavila, ga je peljala s seboj gori s tremi junci in z eno efo moke in z mehom vina in ga je privedla v hišo Gospodovo v Silu; a deček je bil še mlad.',
        25: 'In zaklali so junca in pripeljali dečka k Eliju.',
        26: 'In ona reče: Ah, gospod moj, kakor res živi duša tvoja, gospod moj, jaz sem tista žena, ki sem tu pri tebi stala in Gospoda prosila.',
        27: 'Za tega dečka sem prosila, in Gospod mi je izpolnil prošnjo, ki sem jo prosila od njega.',
        28: 'Zato ga tudi jaz izročam Gospodu; vse dni, dokler bo živel, je izročen Gospodu. In on se je ondi poklonil Gospodu.',
    },
    2: {
        1: 'In Ana je molila in rekla: Srce moje se raduje v Gospodu, rog moj je povišan po Gospodu; usta moja so se široko odprla zoper sovražnike moje, kajti veselim se zveličanja tvojega.',
        2: 'Nihče ni tako svet kakor Gospod, kajti razen tebe ni nobenega; in ni nobene Skale, kakor je naš Bog.',
        3: 'Ne množite govorov o visokih rečeh, predrznost naj ne pride iz vaših ust: kajti Gospod je Bog mogočni, ki vse pozna, in misli človeške na tehtnico deva on.',
        4: 'Močnih lok je zlomljen, a slabotni so opasani z močjo.',
        5: 'Kateri so bili siti, so v službo stopili za kruh, in kateri so lakoto trpeli, niso več lačni; in nerodovitna je rodila sedmero, in katera je veliko imela otrok, je onemogla.',
        6: 'Gospod mori in oživlja, pelje v kraj smrti in zopet nazaj.',
        7: 'Gospod spravi v uboštvo in obogati, on ponižuje, pa tudi povišuje.',
        8: 'On povišuje ubožca iz prahu, siromaka vzdiguje iz blata, da ga posadi med plemenitnike in mu da podedovati slave prestol; kajti Gospodovi so stebri zemlje, in on je nanje postavil svet.',
        9: 'On bo varoval svojih svetnikov noge, ali brezbožniki umolknejo v temi; zakaj po svoji moči človek ne pride kvišku.',
        10: 'Zatrti bodo, kateri nasprotujejo Gospodu, zoper nje bo on grmel v nebesih. Gospod bo sodil kraje zemlje, in da moč kralju svojemu in poviša rog maziljenca svojega.',
        11: 'In Elkana je šel v Ramo v hišo svojo. A deček je bil strežnik Gospodu pred očmi Elija duhovnika.',
        12: 'Sinova Elijeva pa sta bila otroka Belijalova; nista poznala Gospoda.',
        13: 'In navada duhovnikov proti ljudstvu je bila: Kadar je kdo prinesel daritev, je prišel, ko se je meso kuhalo, duhovnikov hlapec s trirogljatimi vilicami v roki,',
        14: 'in je ž njimi sunil v medenico ali v lonec ali v kotel ali v ponev, in karkoli je z vilicami izvlekel, je vzel duhovnik zase. Tako so delali v Silu vsem Izraelcem, ki so prihajali tja.',
        15: 'Enako je prišel tudi, preden so zažgali tolstino, duhovnikov hlapec in rekel možu, ki je opravljal daritev: Daj mesa, da ga opečem duhovniku; zakaj ne bo vzel kuhanega mesa od tebe, temuč sirovo.',
        16: 'Ako je rekel dotičnik: Saj bodo precej zažgali tolstino, potem vzemi, kolikor ti ugaja; tedaj mu je odgovoril: Ne, ampak daj mi ga zdaj, in če ne daš, vzamem s silo.',
        17: 'In greh mladeničev je bil silno velik pred Gospodom, kajti ljudje so zaničevali darila Gospodova.',
        18: 'Samuel pa je stregel pred obličjem Gospodovim, še deček, prepasan s platnenim naramnikom;',
        19: 'k temu mu je leto za letom napravila mati njegova suknjico in mu jo prinesla, ko je prišla gori z možem svojim opravljat vsakoletno daritev.',
        20: 'In Eli je blagoslovil Elkana in ženo njegovo in rekel: Gospod ti daj zarod od te žene namesto darovanega, ki ga je izročila Gospodu! In šli so v hišo svojo.',
        21: 'In Gospod je obiskal Ano, da je spočela in rodila še tri sinove in dve hčeri. A deček Samuel je napredoval pri Gospodu.',
        22: 'Eli pa je bil silno star; in slišal je vse, kar počenjata sinova njegova z vsem Izraelom ter da se družita z ženami, ki so opravljale službo pri vratih shodnega šatora.',
        23: 'In dejal je jima: Zakaj to delata? slišim namreč o vajinih hudih dejanjih od vsega tega ljudstva.',
        24: 'Nikar, sinova moja! zakaj to ni dober glas, ki ga slišim; povzročata, da Gospodovo ljudstvo prestopa.',
        25: 'Ako kdo greši zoper človeka, Bog mu je sodnik; ko pa kdo greši zoper Gospoda, kdo se potegne zanj? Ali nista poslušala glasu očeta svojega; kajti Gospod ju je hotel umoriti.',
        26: 'A deček Samuel je vedno napredoval in je bil prijeten Gospodu in tudi ljudem.',
        27: 'Pride pa mož Božji k Eliju in mu reče: Tako pravi Gospod: Nisem li se razodel očeta tvojega družini, ko so še bili v Egiptu, pri hiši Faraonovi?',
        28: 'In njega sem si izvolil izmed vseh rodov Izraelovih, da bodi moj duhovnik, da daruje na mojem oltarju, da pali kadilo in naramnik nosi pred obličjem mojim; in očeta tvojega hiši sem dal vse daritve, ki jih po ognju darujejo sinovi Izraelovi.',
        29: 'Zakaj teptate daritve moje in jedilna darila meni, ki sem jih zapovedal v prebivališču svojem? In sinova svoja bolj spoštuješ nego mene, da se redite z najboljšim od jedilnih daril Izraela, ljudstva mojega!',
        30: 'Zato pravi Gospod, Bog Izraelov: Rekel sem bil res, da naj bi hiša tvoja in tvojega očeta hiša hodili pred mano vekomaj; ali sedaj pravi Gospod: Ne bodi tako; zakaj tiste, ki me časte, počastim tudi jaz, in ki mene zaničujejo, malo jih bom cenil tudi jaz.',
        31: 'Glej, pridejo dnevi, da odsekam ramo tvojo in ramo hiši očeta tvojega, da ne bo starca v hiši tvoji.',
        32: 'In videl boš le stisko prebivališča mojega, pri vsem dobrem, kar Bog dodeli Izraelu in priletnega ne bode v hiši tvoji vekomaj.',
        33: 'Nočem ti sicer slehernega zatreti od oltarja mojega, ker bi ti usahnile oči in duša ti skoprnela, ali vsa mladina hiše tvoje pomrje v moških letih.',
        34: 'In to ti bodi v znamenje, kar pride na oba sinova tvoja, Ofnija in Pinehasa: obadva umrjeta eden dan.',
        35: 'In obudim si zvestega duhovnika, ki bo delal, kakor je po mojem srcu in po mojih mislih, in njemu sezidam stanovitno hišo; in hodil bo pred maziljencem mojim vse dni.',
        36: 'In zgodi se, da vsak, kdor preostane iz hiše tvoje, pride in se njemu pokloni za srebrn denar in hlebček kruha ter poreče: Prosim, pripusti me vsaj v eno duhovsko službo, da jem grižljaj kruha.',
    },
    3: {
        1: 'Deček Samuel pa je služil Gospodu pred Elijem. In beseda Gospodova je bila redka v tistih dneh, prikazen se ni ponavljala.',
        2: 'In zgodi se v tistem času, ko je Eli ležal na svojem mestu – oči njegove pa so bile že slabotne, da ni videl –',
        3: 'in svetilnica Božja ni bila še ugasnjena, in Samuel je ležal ob svetišču Gospodovem, kjer je bila skrinja Božja,',
        4: 'da pokliče Gospod Samuela; in ta reče: Tu sem!',
        5: 'In teče k Eliju in reče: Tu sem, ker si me klical. On veli: Nisem klical; vrni se in spi! In je šel in legel.',
        6: 'In Gospod zopet kliče: Samuel! In Samuel vstane ter pride k Eliju in reče: Tu sem, ker si me klical. Ta veli: Nisem klical, sin moj, vrni se in spi!',
        7: 'Samuel pa še ni poznal Gospoda, in beseda Gospodova mu še ni bila razodeta.',
        8: 'In Gospod zopet kliče v tretje: Samuel! In vstane ter pride k Eliju in reče: Tu sem, ker si me klical. Tedaj spozna Eli, da je Gospod klical dečka.',
        9: 'Zato veli Eli Samuelu: Pojdi in spi! in če te še pokliče, reci: Govóri, Gospod, ker posluša hlapec tvoj. In Samuel odide in leže na svoje mesto.',
        10: 'In Gospod pride ter stoji in kliče kakor poprej: Samuel, Samuel! In Samuel reče: Govóri, ker posluša hlapec tvoj.',
        11: 'In Gospod reče Samuelu: Glej, jaz storim stvar v Izraelu, da bo zvenelo v obeh ušesih vsakemu, kdor bo slišal o njej.',
        12: 'Tisti dan uresničim proti Eliju vse, kar sem govoril o hiši njegovi; začnem to in dovršim.',
        13: 'Kajti povedal mu sem, da bom sodil hišo njegovo vekomaj zavoljo krivice, ki je vedel zanjo, da si spravljata sinova njegova prokletstvo nadse, pa jima ni zabranil.',
        14: 'In zato sem prisegel hiši Elijevi: Krivica hiše Elijeve se ne bo poravnala z žgalnimi in jedilnimi žrtvami na vekomaj!',
        15: 'In Samuel je ležal do jutra in je odprl vrata hiše Gospodove. Bal se pa je povedati prikazen Eliju.',
        16: 'Tedaj pokliče Eli Samuela, rekoč: Samuel, sin moj! On reče: Glej, tu sem!',
        17: 'In vpraša: Kaj je beseda, ki ti jo je govoril? Prosim, ne zamolči mi ničesar! Bog ti stóri to in ono, ako mi besede zamolčiš iz vsega, kar ti je govoril.',
        18: 'In Samuel mu pove vse do besede, ničesar mu ne zataji. Eli pa reče: Gospod je; naj stori, kar se mu vidi prav!',
        19: 'A Samuel je napredoval, in Gospod je bil ž njim in ni pustil, da pade na zemljo ne ena besed njegovih.',
        20: 'In ves Izrael od Dana do Bersebe je spoznal, da je Samuel potrjen, da bodi prorok Gospodov.',
        21: 'In Gospod se je zopet prikazoval v Silu; kajti Gospod se je razodeval Samuelu v Silu po besedi Gospodovi.',
    },
    4: {
        1: 'In kar je rekel Samuel, je šlo po vsem Izraelu. In Izrael je šel v boj zoper Filistejce; in so se utaborili pri Eben-ezerju, Filistejci pa so se utaborili v Afeku.',
        2: 'In Filistejci so se bojno uvrstili zoper Izraela; in ko se je vnela bitka, je bil Izrael poražen pred Filistejci, in pobili so jih iz bojnih vrst na polju okoli štiri tisoč mož.',
        3: 'In ko se ljudstvo zbere v taboru, reko starejšine Izraelovi: Zakaj nas je Gospod danes udaril pred Filistejci? Vzemimo k sebi iz Sila Gospodovo skrinjo zaveze, da pride med nas in nas reši roke sovražnikov naših.',
        4: 'In ljudstvo pošlje v Silo, in prineso odondod skrinjo zaveze Gospoda nad vojskami, ki stoluje nad kerubi; in dva sinova Elijeva, Ofni in Pinehas, sta bila tam s skrinjo zaveze Božje.',
        5: 'In ko je prišla skrinja zaveze Gospodove v tabor, je zaukal ves Izrael z močnim glasom, da je zemlja odmevala.',
        6: 'Ko pa Filistejci slišijo glas tega ukanja, vprašajo: Kaj pomeni glas takega močnega ukanja v taboru Hebrejcev? In zvedeli so, da je prišla skrinja Gospodova v tabor.',
        7: 'In Filistejci se zboje, kajti pravijo: Bog je prišel v tabor. In reko: Gorje nam! zakaj tega ni bilo včeraj in predvčerajšnjim.',
        8: 'Gorje nam! Kdo nas otme iz roke teh veličastnih bogov? To so bogovi, ki so udarili Egipt v puščavi z mnogoterimi šibami!',
        9: 'Trdni bodite in moški se držite, o Filistejci, da vam ne bo služiti Hebrejcem, kako so oni služili vam; moški se držite in bojujte!',
        10: 'In bojevali so se Filistejci in Izrael je bil premagan, in vsak je bežal v šator svoj; in poboj je bil silno velik, ker je padlo iz Izraela trideset tisoč pešcev.',
        11: 'In skrinja Božja je bila vzeta, in dva sinova Elijeva, Ofni in Pinehas, sta poginila.',
        12: 'In tekel je neki Benjaminec iz bojnih vrst, in pride še ta dan v Silo. In raztrgal si je oblačilo in glavo posipal s prstjo:',
        13: 'In ko pride, glej, Eli sedi na stolu pri poti in pazi: kajti srce mu je bilo v strahu zavoljo skrinje Božje. In ko mož pride v mesto in oznani novico, zavpije vse mesto.',
        14: 'Ko pa Eli sliši glas vpitja, vpraša: Kakšen je to glasan šum? In mož hitro pristopi in pove Eliju.',
        15: 'Eli pa je bil osemindevetdeset let star, in oči so mu bile ugasnile, da ni mogel videti.',
        16: 'In mož reče Eliju: Jaz sem prišel iz vojske, in sicer sem pobegnil iz bitke danes. On pa vpraša: Kako se je godilo, sin moj.',
        17: 'In sporočnik odgovori in reče: Izrael je zbežal pred Filistejci, vrhutega je bil velik poboj med ljudstvom, tudi dva sinova tvoja, Ofni in Pinehas, sta mrtva, in skrinja Božja je vzeta!',
        18: 'Ko pa je oni imenoval skrinjo Božjo, pade Eli s stola znak pri vratih in si zlomi šijnjak in umre; kajti bil je star in težak mož. In on je sodil Izraela štirideset let.',
        19: 'Njegova snaha pa, žena Pinehasova, je bila noseča in je imela skoraj roditi. In ko zasliši vest, da je skrinja Božja vzeta in da je mrtev njen tast in njen mož, se sključi in porodi, kajti bolečine so jo prijele.',
        20: 'In ko se je bližala smrti, so rekle žene, ki so stale pri njej: Ne boj se, saj si rodila sina! A ona ni odgovorila ničesar in si srca ni utolažila;',
        21: 'in dete je imenovala Ikabod, rekoč: Slava je šla strani od Izraela – ker je bila vzeta skrinja Božja in zaradi njenega tasta in njenega moža.',
        22: 'In je dejala: Slava je šla strani od Izraela, ker je vzeta skrinja Božja.',
    },
    5: {
        1: 'Filistejci so pa vzeli skrinjo Božjo in jo donesli iz Eben-ezerja v Asdod.',
        2: 'In Filistejci vzemo skrinjo Božjo in jo prineso v hišo Dagonovo in jo postavijo poleg Dagona.',
        3: 'Ko pa Asdodci zgodaj zjutraj vstanejo, vidijo, da je Dagon padel z obrazom na tla pred skrinjo Gospodovo. In vzdignejo Dagona in ga zopet postavijo na mesto njegovo.',
        4: 'Toda ko zgodaj vstanejo drugo jutro, glej, Dagon je bil spet padel z obrazom na tla pred skrinjo Gospodovo; in glava Dagonova in obe pesti rok njegovih so bile odsekane na pragu, samo ribasti trup ga je bil ostal.',
        5: 'Zatorej ne stopajo duhovniki Dagonovi, ne drugi, kolikor jih hodi v hišo njegovo, na prag Dagonov v Asdodu do tega dne.',
        6: 'Roka Gospodova pa je bila težka nad Asdodci, in jih je trl ter jih udaril s tvori v Asdodu in po vsej okolici.',
        7: 'In ko so videli možje v Asdodu, da se jim tako godi, reko: Naj ne ostane skrinja Boga Izraelovega pri nas, kajti roka njegova je pretrda nad nami in nad našim bogom Dagonom!',
        8: 'In pošljejo in zbero k sebi vse kneze Filistejcev in reko: Kaj naj storimo s skrinjo Boga Izraelovega? Oni pa odgovore: Naj se prenese skrinja Boga Izraelovega v Gat! Prenesli so torej tja skrinjo Boga Izraelovega.',
        9: 'Zgodi se pa, potem ko so jo prenesli, da je bila roka Gospodova zoper mesto in je napravila silno veliko zmešnjavo, ker je udaril ljudi v mestu, od najmanjšega do največjega, da so se jim tvori izpustili.',
        10: 'Pošljejo torej skrinjo Božjo v Ekron. Ali ko pride skrinja Božja v Ekron, zavpijejo Ekronci in reko: Prinesli so skrinjo Boga Izraelovega k nam, da nas pogubi in ljudstvo naše.',
        11: 'Pošljejo torej in skličejo vse kneze Filistejcev in reko: Odpošljite skrinjo Boga Izraelovega, da se povrne na mesto svoje, da ne pogubi nas in ljudstva našega! Kajti smrtna zmešnjava je bila po vsem mestu; roka Božja je bila pretežka ondi.',
        12: 'In kateri niso umrli, so bili udarjeni s tvori; in vpitje iz mesta je šlo gori proti nebu.',
    },
    6: {
        1: 'In skrinja Gospodova je bila v kraju Filistejcev sedem mesecev.',
        2: 'In Filistejci pokličejo svoje duhovnike in vedeže in reko: Kaj naj storimo s skrinjo Gospodovo? Poučite nas, s čim naj jo pošljemo v njen kraj?',
        3: 'Oni odgovore: Ako hočete vrniti skrinjo Boga Izraelovega, ne pošljite je prazne, temuč vsekakor mu dajte daritev za krivdo; tedaj ozdravite in spoznate, zakaj se roka njegova ni umeknila od vas.',
        4: 'In vprašajo: Kaj bodi za krivdo daritev, ki mu jo naj damo? Oni reko: Pet zlatih tvorov in pet zlatih miši, po številu knezov filistejskih; zakaj ista nadloga je bila nad vami vsemi in nad vašimi knezi.',
        5: 'Naredite torej podobe tvorov svojih in podobe miši, ki so deželo vašo kazile, in dajte čast Bogu Izraelovemu; morda olajša roko svojo nad vami in nad vašim bogom in nad vašo zemljo.',
        6: 'Zakaj pa zakrkujete srce svoje, kakor so si ga Egipčani in Faraon zakrknili? Ko je Bog izkazal med njimi moč svojo, niso li pustili ljudstva, da je odšlo?',
        7: 'Sedaj pa si pripravite nov voz in vzemite dve doječi kravi, ki še nista nosili jarma, in vprezite kravi v voz, njiju teleti pa, ko pojdeta za njima, odpeljite domov.',
        8: 'In vzemite skrinjo Gospodovo in jo postavite na voz, zlate dragotine pa, ki mu jih daste v daritev za krivdo, denite v skrinjico ob njeni strani, in pošljite jo tja, da odide.',
        9: 'In glejte: če pojde po poti gori, proti svoji meji, k Betsemesu, je On nam storil vse tisto zlo veliko; ako pa ne, bomo vedeli, da nas ni njegova roka udarila, temuč po naključbi se nam je zgodilo.',
        10: 'In možje so storili tako; in vzamejo dve doječi kravi in ju vprežejo v voz, njiju teleti pa zaklenejo doma.',
        11: 'In skrinjo Gospodovo nalože na voz, tudi skrinjico z zlatimi mišmi in podobami svojih tvorov.',
        12: 'In kravi sta krenili naravnost proti Betsemesu, po cesti, in sta šli in mukali in se nista umeknili ne na desno, ne na levo. In knezi Filistejcev so šli za njimi do meje Betsemesa.',
        13: 'Betsemeščani pa so ravno želi pšenico v dolini. In ko povzdignejo oči, ugledajo skrinjo in se razvesele, da jo vidijo.',
        14: 'Voz pa pride na njivo Jozueta Betsemeščana in se tam ustavi. In bil je ondi velik kamen; in razsekajo les od voza in darujejo kravi v žgalno daritev Gospodu.',
        15: 'Leviti pa so vzdignili skrinjo Gospodovo in skrinjico, ki je bila pri njej in v kateri so bile tiste zlate dragotine, in ju postavili na tisti veliki kamen; in ljudje iz Betsemesa so ta dan darovali žgalščine in klalščine Gospodu.',
        16: 'In ko je to videlo petero knezov filistejskih, se vrnejo v Ekron še tisti dan.',
        17: 'To pa so zlati tvori, ki so jih dali Filistejci v dar za krivdo Gospodu: za Asdod eden, za Gazo eden, za Askelon eden, za Gat eden, za Ekron eden.',
        18: 'In zlatih miši so dali po številu vseh mest Filistejcev, podložnih peterim knezom, za ograjena mesta in za vasi po deželi. In priča je tisti veliki kamen, na katerem so postavili skrinjo Gospodovo, do današnjega dne na njivi Jozueta Betsemeščana.',
        19: 'Udaril pa je nekatere betsemeške može, ker so gledali v skrinjo Gospodovo; udaril je namreč izmed ljudstva sedemdeset mož iz petdesettisoč mož. In žalovalo je ljudstvo, ker je bil Gospod napravil tako velik pomor v ljudstvu.',
        20: 'In betsemeški ljudje so dejali: Kdo more stati pred Gospodom, tem svetim Bogom? In h komu naj gre od nas?',
        21: 'In pošljejo sle prebivalcem v Kirjat-jearimu in sporoče: Filistejci so nazaj pripeljali skrinjo Gospodovo; pridite doli, vzemite jo gori k sebi!',
    },
    7: {
        1: 'In pridejo možje kirjat-jearimski in vzemo gori skrinjo Gospodovo in jo prineso v hišo Abinadabovo na griču, in Eleazarja, sina njegovega, posvetijo, da varuje skrinjo Gospodovo.',
        2: 'In preminilo je od dne, ko je ostala skrinja v Kirjat-jearimu, dosti časa, da je bilo dvajset let; in vsa hiša Izraelova je žalovala za Gospodom.',
        3: 'In Samuel ogovori vso družino Izraelovo, rekoč: Ako se hočete iz vsega srca izpreobrniti h Gospodu, odpravite izmed sebe tuje bogove in Astarte in obrnite srce svoje h Gospodu in služite njemu samemu; in otme vas iz pesti Filistejcev.',
        4: 'Tedaj so sinovi Izraelovi odpravili izmed sebe Baale in Astarte, in so služili Gospodu samemu.',
        5: 'In Samuel veli: Skličite vsega Izraela v Micpo, in molil bom za vas Gospoda.',
        6: 'In ko so se zbrali v Micpi, so zajemali vodo in jo izlivali pred Gospodom, in so se postili tisti dan in priznavali: Grešili smo zoper Gospoda. In Samuel je sodil sinove Izraelove v Micpi.',
        7: 'Ko pa zaslišijo Filistejci, da so se zbrali sinovi Izraelovi v Micpi, odrinejo knezi Filistejcev gori proti Izraelu. Ko to slišijo sinovi Izraelovi, se zboje Filistejcev.',
        8: 'In reko sinovi Izraelovi Samuelu: Ne nehaj za nas vpiti h Gospodu, Bogu našemu, da nas reši roke Filistejcev!',
        9: 'In Samuel vzame jagnje od sesca ter celo daruje v žgalno žrtev za Izraela; in Samuel vpije h Gospodu zastran Izraela, in Gospod mu je odgovoril.',
        10: 'Ko je namreč Samuel daroval žgalno žrtev, se približajo Filistejci, da se vojskujejo z Izraelom, ali Gospod zagrmi tisti dan nad Filistejci z grmenjem velikim in jih zbega; in bili so poraženi pred Izraelom.',
        11: 'In možje Izraelovi pridejo iz Micpe ter pode Filistejce in jih pobijajo do kraja, ki je pod Betkarjem.',
        12: 'Tedaj vzame Samuel kamen in ga postavi med Micpo in Šenom ter mu da ime Eben-ezer, rekoč: Doslej nam je pomagal Gospod.',
        13: 'Tako so bili Filistejci ponižani, in niso prišli več v Izraelovo pokrajino. In roka Gospodova je bila zoper Filistejce vse Samuelove dni.',
        14: 'Tudi mesta, ki so jih bili vzeli Filistejci Izraelu, je dobil Izrael nazaj, od Ekrona do Gata; tudi njih pokrajine je otel Izrael iz roke Filistejcev. Bil pa je mir med Izraelom in Amorejci.',
        15: 'In Samuel je sodil Izraela vse svoje žive dni.',
        16: 'In hodeč vsako leto okrog, je postajal v Betelu, Gilgalu in Micpi, in je sodil Izraelu v vseh teh krajih.',
        17: 'Potem se je vračal v Ramo, zakaj ondi je bila hiša njegova, in ondi je sodil Izraelu, in ondi je zgradil oltar Gospodu.',
    },
    8: {
        1: 'Ko pa se je postaral Samuel, je postavil svoja sinova za sodnika Izraelu.',
        2: 'Ime prvencu njegovemu je bilo Joel, drugemu pa Abija: ta sta bila sodnika v Bersebi.',
        3: 'A sinova njegova nista hodila po njegovi poti, temuč sta se nagnila k lakomnosti in sta jemala darila in zavijala pravico.',
        4: 'Tedaj se zbero vsi starejšine Izraelovi in pridejo k Samuelu v Ramo',
        5: 'in mu reko: Glej, ti si se postaral, in sinova tvoja ne hodita po tvojem potu: postavi nam torej kralja, da nas sodi, kakor imajo vsi narodi.',
        6: 'To pa se je hudo videlo Samuelu, da so rekli: Daj nam kralja, da nas sodi. In Samuel je molil h Gospodu.',
        7: 'A Gospod reče Samuelu: Poslušaj ljudstva glas v vsem, kar so ti govorili, zakaj niso zavrgli tebe, ampak mene, da ne bi jim bil kralj.',
        8: 'Tudi tebi delajo, kakor so vselej delali od dne, ko sem jih peljal iz Egipta, do tega dne, ko so me zapuščali in služili drugim bogovom.',
        9: 'Zdaj torej poslušaj njih glas; toda resno jim izpričaj njih napako in jim naznani pravico kralja, ki jim bo kraljeval.',
        10: 'In Samuel pove ljudstvu, ki je zahtevalo kralja, vse besede Gospodove',
        11: 'in reče: To bode pravica kralja, ki vam bo kraljeval: Jemal bo sinove vaše in si jih postavi, da so nad njegovimi vozovi in da so mu konjiki, in tekali bodo pred njegovimi vozovi;',
        12: 'in si jih postavi za tisočnike in petdesetnike in nekatere, da mu orjejo njive in spravljajo njegove letine ter da mu izgotavljajo bojno orožje in naprave za vozove.',
        13: 'Vaše hčere pa bo jemal, da mu bodo mazilarice, kuharice in kruharice.',
        14: 'Tudi bo jemal vaše najboljše njive, vinograde in oljske vrtove ter jih dajal svojim hlapcem.',
        15: 'Desetinil bo tudi vaše setve in vinograde in dajal dvornikom in hlapcem svojim.',
        16: 'In bo jemal vaše hlapce in dekle in najlepše mladeniče in osle vaše ter ž njimi opravljal svoje delo.',
        17: 'Tudi črede vaše bo desetinil, in vi mu boste morali biti hlapci.',
        18: 'In tisti čas boste vpili zaradi kralja svojega, ki ste si ga izvolili, a Gospod vas tisti čas ne bo uslišal.',
        19: 'Ljudstvo pa se brani poslušati glas Samuelov, in reko: Kratko ne; temuč kralja hočemo imeti,',
        20: 'da bodemo tudi mi kakor vsi drugi narodi ter da nas sodi naš kralj in hodi pred nami in vodi boje naše.',
        21: 'In ko je Samuel slišal vse besede ljudstva, jih je povedal Gospodu na ušesa.',
        22: 'Gospod pa veli Samuelu: Poslušaj le njih glas in jim stóri kralja. In Samuel reče Izraelovim možem: Pojdite vsak v mesto svoje!',
    },
    9: {
        1: 'Bil pa je mož iz Benjamina, po imenu Kis, sin Abiela, sina Zerorja, sina Bekorata, sina Afija, sina enega Benjamincev, vrl junak.',
        2: 'In imel je sina z imenom Savla, mladega in lepega, in ni ga bilo med sinovi Izraelovimi lepšega od njega; za glavo je bil višji nego kdorkoli iz ljudstva.',
        3: 'Izgubile so se pa oslice Kisu, očetu Savlovemu. In Kis veli Savlu, sinu svojemu: Vzemi s sabo iz hlapcev enega ter vstani in pojdi iskat oslice.',
        4: 'In prehodi Efraimovo gorovje in gre dalje skozi pokrajino Saliso, a jih ne najdeta; nato prehodita pokrajino Salim, in ni jih bilo ondi, in potem prehodita deželo Benjamincev, a jih ne najdeta.',
        5: 'Ko prideta v Zufsko pokrajino, reče Savel hlapcu svojemu, ki je bil ž njim: Pojdi, vrniva se domov, ker pusti oče moj iz misli oslice in bo skrbel za naju.',
        6: 'On pa mu reče: Poglej, prosim, v tem mestu je mož Božji, in njega čislajo visoko; vse, kar on pravi, se gotovo zgodi. Pojdiva torej tja; lahko nama pove pot, po kateri naj greva.',
        7: 'Nato reče Savel hlapcu svojemu: Ali, glej, če pojdeva, kaj prineseva tistemu možu? Kruh nama je pošel v torbah, in nimava daru, ki bi ga prinesla možu Božjemu. Kaj imava?',
        8: 'Hlapec spet odgovori Savlu in reče: Glej, imam četrtino srebrnega sekla pri sebi, to hočem dati možu Božjemu, da nama pove najino pot.',
        9: '(Nekdaj so dejali v Izraelu, ko so šli Boga vprašat: Pojdite, naj gremo k vidcu! Kdor se zdaj imenuje prorok, se je namreč nekdaj imenoval videc.)',
        10: 'Tedaj veli Savel hlapcu svojemu: Prav si govoril. Na noge, da greva! In šla sta v mesto, kjer je bil mož Božji.',
        11: 'Ko gresta gori po strmini proti mestu, srečata dekleta, ki so šla ven vodo zajemat, in jih vprašata: Je li videc tukaj?',
        12: 'One jima odgovore in reko: Da, glej, pred teboj je; le híti, zakaj danes je prišel v mesto, ker ljudstvu je danes daritev opraviti na višavi.',
        13: 'Ko prideta v mesto, ga precej najdeta, preden pojde na višavo jest; zakaj ljudstvo ne bo jedlo, dokler on ne pride, ker on blagoslovi daritev; potem jedo, kateri so povabljeni. Pojdita torej tja gori, kajti prav zdaj se bosta na njega namerila.',
        14: 'Šla sta torej gori v mesto. In ko stopita v sredo mesta, glej, Samuel izide, njima na proti, in hoče iti na višavo.',
        15: 'Gospod pa je dan poprej, preden je bil prišel Savel, razodel Samuelu, rekoč:',
        16: 'Jutri ob tem času ti pošljem moža iz Benjaminove dežele, in njega pomazili za vojvodo ljudstvu mojemu Izraelu, da reši ljudstvo moje iz roke Filistejcev; kajti pogledal sem na ljudstvo svoje, ker njegovo vpitje je prišlo do mene.',
        17: 'In ko Samuel ugleda Savla, mu odgovori Gospod: Glej, to je mož, ki ti sem o njem povedal! Ta bo gospodoval ljudstvu mojemu.',
        18: 'V tem pristopi Savel k Samuelu med vrati in vpraša: Povej mi, prosim, kje je tu vidčeva hiša?',
        19: 'Samuel odgovori in reče: Jaz sem videc. Pojdi pred menoj na višavo, zakaj danes bosta jedla z mano, in zjutraj te odpustim, in karkoli je v tvojem srcu, ti povem.',
        20: 'A za oslice, ki so se ti izgubile pred tremi dnevi, nič zdaj ne skrbi, kajti našli so jih. A na koga meri vsa želja Izraelova? Ne li nate in na tvojega očeta vso hišo?',
        21: 'Savel odgovori in reče: Nisem li jaz Benjaminec, iz najmanjšega rodu v Izraelu? in rodovina moja je najmanjša vseh rodovin Benjaminovega rodu. Zakaj mi takole govoriš?',
        22: 'Samuel pa vzame Savla in hlapca njegovega ju pelje v dvorano in ju posadi odzgoraj med povabljence, katerih je bilo okoli trideset mož.',
        23: 'In Samuel veli kuharju: Daj sem tisti kos, ki sem ti ga dal in velel, da ga pri sebi ohraniš.',
        24: 'Tedaj prinese kuhar stegno in kar se ga je držalo ter položi to pred Savla. In Samuel reče: Glej, to smo prihranili, vzemi predse in jej; kajti za določeni čas se je ohranilo zate, ker sem rekel: Ljudstva sem povabil. In Savel je jedel s Samuelom tisti dan.',
        25: 'In ko so prišli doli z višave v mesto, je govoril s Savlom na strehi.',
        26: 'In zjutraj zgodaj vstaneta. In ko zora vzhaja, pokliče Samuel Savla na strehi, rekoč: Vstani, da te spremim. In Savel vstane, in gresta ven obadva skupaj, on in Samuel.',
        27: 'In ko sta prišla na konec mesta, veli Samuel Savlu: Reci hlapcu, naj pred nama gre naprej. In on gre naprej. Ti pa zdaj mirno stoj, da ti oznanim, kar je Bog govoril.',
    },
    10: {
        1: 'Tedaj vzame Samuel oljeníco in mu izlije olje na glavo ter ga poljubi in reče: Te li ni Gospod pomazilil, da bodi vojvoda dediščini njegovi?',
        2: 'Ko pojdeš od mene danes, srečaš dva moža pri Rahelinem grobu, v Benjaminovi pokrajini, ob Zelzahu; in ona ti porečeta: Našle so se oslice, ki si jih šel iskat; in glej, oče tvoj je pustil iz misli oslice in skrbi za vaju, govoreč: Kaj naj počnem za sina svojega?',
        3: 'In ko pojdeš odondod dalje, prideš k hrastu Taboru, in ondi te srečajo trije možje, gredoči gori k Bogu v Betel: eden nese tri kozliče, drugi tri hlebe kruha, tretji meh vina.',
        4: 'Pa te pozdravijo in ti dado dva hleba kruha, ki ju sprejmi iz njih roke.',
        5: 'Potem prideš na hrib Božji, kjer stoje straže Filistejcev, in ko stopiš ondi v mesto, srečaš družbo prorokov, gredočih doli z višave, in pred njimi bodo psalmove brenklje in bobnice in piščal in harfa, in bodo prorokovali.',
        6: 'In duh Gospodov pride z močjo nadte, in prorokoval boš ž njimi, in izpremenjen boš v drugega moža.',
        7: 'In ko se ti dogode ta znamenja, stóri, kar ti pod roko pride, kajti Bog je s teboj.',
        8: 'In pridi pred menoj doli v Gilgal, in glej, pridem tja k tebi, da darujem žgalne in mirovne daritve. Sedem dni počakaj, da pridem k tebi in ti naznanim, kar ti je storiti.',
        9: 'In bilo je, ko je obrnil hrbet in šel od Samuela, da mu je Bog izpremenil srce; in vsa tista znamenja so se dogodila ta dan.',
        10: 'Kajti ko prideta tja k hribu, glej, družba prorokov ga sreča, in duh Božji pride z močjo nad njega, da je prorokoval med njimi.',
        11: 'Ko ga pa vidijo tisti, ki so ga poprej poznali, da prorokuje s proroki, reko vsi drug drugemu: Kaj se je prigodilo sinu Kisovemu? Je li Savel tudi med proroki?',
        12: 'In nekdo ondotnih odgovori in reče: In kdo je njih oče? Odtod je prišlo v pregovor: Je li tudi Savel med proroki?',
        13: 'In neha prorokovati in pride na višavo.',
        14: 'Savlov stric pa reče njemu in njegovemu hlapcu: Kam sta bila šla? Odgovori: Oslice iskat, in ko sva videla, da jih ni, sva šla k Samuelu.',
        15: 'Nato de Savlov stric: Povej mi, prosim, kaj vama je povedal Samuel?',
        16: 'Savel odgovori stricu svojemu: Povedal je nama za gotovo, da so se oslice našle. Ali zastran kraljestva, o katerem je govoril Samuel, mu ničesar ne pove.',
        17: 'Samuel pa skliče ljudstvo h Gospodu v Micpo,',
        18: 'in ogovori sinove Izraelove: Tako pravi Gospod, Bog Izraelov: Jaz sem pripeljal Izraela iz Egipta in vas otel iz pesti Egipčanov in iz oblasti vseh kraljestev, ki so vas tlačila.',
        19: 'A vi ste danes zavrgli svojega Boga, ki vas je sam rešil iz vseh nesreč in nadlog vaših, in ste mu rekli: Postavi nam kralja! Sedaj pa pristopite pred Gospoda po rodovih svojih in po tisočih svojih!',
        20: 'In ko je Samuel velel pristopiti vsem rodovom Izraelovim, je bil zadet rod Benjaminov.',
        21: 'In veli pristopiti Benjaminovemu rodu po njih rodovinah, in zadeta je bila rodovina Matri, in zadet je bil Savel, sin Kisov. In ga so iskali, pa ga niso našli.',
        22: 'Zato vprašajo Gospoda še dalje: Pride li še ta mož semkaj? Gospod odgovori: Glej, skril se je med prtljago.',
        23: 'In tečejo tja ter ga pripeljejo. In ko stopi med ljudstvo, je bil za glavo višji nego kdorkoli iz ljudstva.',
        24: 'In Samuel reče vsemu ljudstvu: Vidite ga, ki si ga je izvolil Gospod? Saj mu ni enakega med vsem ljudstvom! Tedaj zauka vse ljudstvo in reče: Živel kralj!',
        25: 'Nato oznani Samuel ljudstvu pravice kraljestva in jih zapiše v knjigo in jo položi pred Gospoda. In odpusti Samuel vse ljudstvo, vsakega v hišo njegovo.',
        26: 'Tudi Savel je šel v hišo svojo v Gibei, in ž njim so šli vojščaki, katerih src se je Bog dotaknil.',
        27: 'Belijalovi sinovi pa reko: Ta naj bi nam pomagal? In so ga zaničevali, in mu niso prinesli darov. Ali on se je delal, kakor da bi ne bil slišal.',
    },
    11: {
        1: 'Tedaj pride gori Nahas, Amonec, in se utabori proti Jabesu v Gileadu. In vsi prebivalci v Jabesu reko Nahasu: Skleni zavezo z nami, in hočemo ti služiti.',
        2: 'Nahas pa, Amonec, jim reče: S tem pogojem se vam zavežem, da vam iztaknem vsem desno oko, in to sramoto spravim nad vsega Izraela.',
        3: 'In starejšine v Jabesu mu reko: Daj nam sedem dni odloga, da pošljemo sle po vseh Izraelovih krajih. Ako ne bo nikogar, da bi nas otel, pridemo k tebi ven.',
        4: 'In pridejo sli v Gibeo Savlovo, in govore te besede vpričo ljudstva; in vse ljudstvo vzdigne glas in zaplaka.',
        5: 'In glej, Savel pride gredoč za voli s polja in vpraša: Kaj je ljudstvu, da joče? In mu pripovedujejo besede mož v Jabesu.',
        6: 'Ko sliši take besede, pride nadenj duh Božji z močjo, in srd njegov se silno razvname.',
        7: 'In vzame par volov in ju razseka in pošlje kosce po slih v vse Izraelove kraje in sporoči: Kdorkoli ne pojde za Savlom in za Samuelom, ž njegovo govedjo naredimo enako! In prešine strah Gospodov ljudstvo, in se vzdignejo kakor en mož.',
        8: 'In preštel jih je v Bezeku, in sinov Izraelovih je bilo tristokrat tisoč in mož Judovih trideset tisoč.',
        9: 'In reko slom, ki so bili prišli: Tako povejte možem v Gileadskem Jabesu: Jutri, ko bo solnce najbolj pripekalo, vam pride rešitev. Ko dospejo sli in oznanijo to možem v Jabesu, se razvesele.',
        10: 'Zato reko meščani v Jabesu sovražniku: Jutri pridemo k vam, in storite nam, karkoli se vam zdi prav.',
        11: 'Drugega jutra razpostavi torej Savel ljudstvo v tri krdela, in ob jutranji straži pridero v tabor Amoncev in jih pobijajo, dokler ni dan prevroč; in kar jih je preostalo, so bili razkropljeni, da nista dva ostala vkup.',
        12: 'Tedaj reče ljudstvo Samuelu: Kdo je ta, ki je rekel: Ali nam bo Savel gospodoval? Dajte sem tiste može, da jih umorimo!',
        13: 'A Savel veli: Ta dan ne sme nihče umreti, zakaj danes je dal Gospod rešitev v Izraelu.',
        14: 'Nato reče Samuel ljudstvu: Pojdite, naj gremo v Gilgal in ondi ponovimo kraljestvo!',
        15: 'In vse ljudstvo gre v Gilgal in ondi postavijo Savla za kralja pred Gospodom v Gilgalu, in tam so darovali žrtve, mirovne daritve pred Gospodom. In Savel in vsi Izraelovi možje so se ondi silno veselili.',
    },
    12: {
        1: 'Samuel pa reče vsemu ljudstvu: Glej, poslušal sem glas vaš v vsem, kar ste mi govorili, in postavil sem vam kralja.',
        2: 'Sedaj pa, glejte, kralj vaš vam hodi na čelu; a jaz sem se postaral in osivel, in glejte, sinova moja sta pri vas; in jaz sem pred vami živel od svoje mladosti do današnjega dne.',
        3: 'Glejte, tu sem! Izpričajte zoper mene pred Gospodom in pred maziljencem njegovim: komu sem vzel vola? ali komu sem vzel osla? ali sem komu krivico delal ali silo? iz čigave roke sem vzel darilo in si dal zagrniti oči zaradi njega? Vse vam hočem povrniti.',
        4: 'Odgovore: Nisi nam storil krivice, ne sile, tudi nisi iz nikogar roke kaj vzel.',
        5: 'On reče: Gospod je priča zoper vas in njegov maziljenec je priča današnji dan, da niste ničesar našli v roki moji. In reko: Priča je!',
        6: 'In Samuel reče ljudstvu: Gospod je priča, ki je postavil Mojzesa in Arona in ki je peljal očete vaše iz Egiptovske dežele.',
        7: 'Sedaj pa postojte tu; da se z vami pravdam pred Gospodom za vsa pravična dela Gospodova, ki jih je storil vam in očetom vašim.',
        8: 'Ko je Jakob prišel v Egipt, so vaši očetje vpili h Gospodu, in Gospod je poslal Mojzesa in Arona; ta sta odvedla očete vaše iz Egipta, in dal jim je prebivališče v tem kraju.',
        9: 'Ali ko so pozabili Gospoda, Boga svojega, jih je prodal v roko Siseru, poveljniku vojske v Hazorju, in v roko Filistejcem in v roko kralju Moabcev, in bojevali so se zoper nje.',
        10: 'Oni pa so vpili h Gospodu in dejali: Grešili smo, ker smo zapustili Gospoda in smo služili Baalom in Astarotam; sedaj pa nas otmi iz sovražnikov naših roke, in bomo ti služili.',
        11: 'In Gospod je poslal Jerub-baala in Bedana in Jefta in Samuela in vas je otel iz roke sovražnikov vaših kroginkrog, in prebivali ste brez skrbi.',
        12: 'Ko pa ste videli, da je pridrl nad vas Nahas, kralj Amonovih sinov, ste mi rekli: Nikar, ampak kralj naj gospoduje nad nami, ko vam je vendar bil kralj Gospod, vaš Bog.',
        13: 'Sedaj pa glejte kralja, ki ste si ga izvolili in si ga izprosili; kajti, glejte, Gospod je postavil kralja nad vami.',
        14: 'Ako se boste bali Gospoda in njemu služili in glas njegov poslušali in se ne boste upirali povelju Gospodovemu, a boste hodili vi in kralj vaš za Gospodom, Bogom svojim, blagor vam.',
        15: 'Ako pa ne boste poslušali glasu Gospodovega, temuč se boste upirali povelju Gospodovemu, bode roka Gospodova zoper vas, kakor je bila zoper očete vaše.',
        16: 'Sedaj pa postojte tu in glejte to reč veliko, ki jo stori Gospod pred vašimi očmi.',
        17: 'Ni li zdaj pšenična žetev? Jaz pa hočem klicati Gospoda, naj spusti grmenje in dež, da spoznate in vidite, kolikšno je zlo, ki ste ga storili pred očmi Gospodovimi, proseč si kralja.',
        18: 'Nato kliče Samuel h Gospodu, in Gospod pošlje grmenje in dež tisti dan; in vse ljudstvo se je silno balo Gospoda in Samuela.',
        19: 'In vse ljudstvo reče Samuelu: Prosi Gospoda, Boga svojega, za nas hlapce svoje, da ne umrjemo; zakaj vsem grehom svojim smo pridejali še to zlo, da smo si prosili kralja.',
        20: 'Samuel pa reče ljudstvu: Ne bojte se! Res ste vse to zlo storili, ali vendar ne odstopite, da ne bi šli za Gospodom, ampak služite Gospodu iz vsega srca.',
        21: 'Ne odstopite, da bi šli za ničevimi maliki, kajti ne morejo vam koristiti, ne vas rešiti, zakaj ničevosti so.',
        22: 'Zakaj Gospod ne zapusti ljudstva svojega zaradi velikega imena svojega, ker je blagovolil Gospod vas storiti sebi za ljudstvo.',
        23: 'Tudi jaz – Bog ne daj, da bi se tako pregrešil Gospodu, da neham moliti za vas, temuč učiti vas hočem dobro in pravo pot.',
        24: 'Bojte se le Gospoda in v resnici mu služite iz vsega srca svojega, kajti vidite, kakšne velike reči je storil za vas.',
        25: 'Ako pa boste vendarle hudo delali, poginete vi in kralj vaš.',
    },
    13: {
        1: 'Savel je bil (trideset) let star, ko je zakraljeval, in ko je kraljeval dve leti Izraelu,',
        2: 'si je izbral tri tisoč mož iz Izraela, katerih sta bila dva tisoča s Savlom v Mikmasu in na Betelskem gorovju in en tisoč je bil z Jonatanom v Gibei Benjaminovi; drugo ljudstvo pa je razpustil, vsakega v šator njegov.',
        3: 'In Jonatan je pobil stražo Filistejcev, ki je bila v Gebi, in Filistejci so to slišali. Savel pa veli trobentati po vsej deželi, rekoč: Naj slišijo Hebrejci!',
        4: 'In ves Izrael je slišal praviti: Savel je pobil Filistejcev stražo, in tudi Izrael se je omrzil Filistejcem. In ljudstvo je bilo sklicano za Savlom v Gilgal.',
        5: 'Tedaj se zbero Filistejci na boj zoper Izraela, trideset tisoč voz, šest tisoč konjikov in ljudstva množina, kolikor je peska na bregu morskem; in pridejo gori in se utabore v Mikmasu, vzhodno od Betavena.',
        6: 'In možje Izraelovi vidijo, da so v tesnobi, kajti ljudstvo je bilo prestrašeno. In ljudstvo se je poskrilo po votlinah in šumah in po skalnih razpoklinah in kleteh in jamah.',
        7: 'Nekateri Hebrejci pa so šli čez Jordan v Gadsko in Gileadsko pokrajino; a Savel je bil še v Gilgalu, in vse ljudstvo je šlo trepetajoč za njim.',
        8: 'In čakal je sedem dni, toliko, kolikor je bil določil Samuel. Samuel pa ni prišel v Gilgal, in ljudstvo se je raztekalo od njega.',
        9: 'Tedaj veli Savel: Prinesite žgalne in mirovne daritve sem k meni! In daroval je žgalščino.',
        10: 'Komaj pa konča darovanje žgalščine, glej, pride Samuel. In Savel mu stopi naproti, da ga pozdravi.',
        11: 'Samuel pa reče: Kaj si storil? Savel odgovori: Ko sem videl, da se mi ljudstvo razteka in da nisi prišel ob določenih dnevih ter da so se Filistejci zbrali v Mikmasu,',
        12: 'sem dejal: Zdaj pridero Filistejci doli nadme v Gilgal, in naklonjenosti Gospodove še nisem izprosil; tedaj sem se osmelil, in daroval sem žgalno daritev.',
        13: 'Samuel pa reče Savlu: Nespametno si ravnal, nisi ohranil zapovedi Gospoda, Boga svojega, ki ti jo je zapovedal; zakaj zdaj bi bil Gospod potrdil kraljestvo tvoje nad Izraelom za vekomaj.',
        14: 'Sedaj pa kraljestvu tvojemu ni obstanka. Poiskal si je Gospod moža po srcu svojem, in njemu je Gospod zapovedal, naj bo vojvoda ljudstvu njegovemu; ker ti nisi ohranil, kar ti je bil zapovedal Gospod.',
        15: 'In Samuel vstane ter odide gori iz Gilgala v Gibeo Benjaminovo. Savel pa prešteje ljudstvo, ki je bilo pri njem, okoli šeststo mož.',
        16: 'In Savel in Jonatan, sin njegov, in ljudstvo, ki je bilo pri njiju, ostanejo v Gebi Benjaminovi; Filistejci pa so taborili v Mikmasu.',
        17: 'In iz tabora Filistejcev pridejo tri krdela, da bi plenili deželo: prvo krdelo se obrne na pot, ki drži v Ofro, proti Sualski pokrajini;',
        18: 'drugo krdelo pa krene na pot v Bet-horon, in tretje krene na pot proti meji, ki se vzdiguje nad Zeboimsko dolino proti puščavi.',
        19: 'Kovača pa ni bilo dobiti po vsej Izraelovi deželi, kajti Filistejci so bili rekli: Da si ne napravijo Hebrejci mečev in sulic!',
        20: 'Zato so morali vsi Izraelci hoditi doli k Filistejcem, kadar je kdo dal ostriti lemež svoj, motiko in sekiro in lopato svojo,',
        21: 'kadar se je skrhala ostrina na lopatah in motikah in vilah in sekirah; in tudi poostriti osten.',
        22: 'Tako je prišlo, ko je nastala vojska, da ni bilo ne meča ne sulice v roki vsega ljudstva, ki je bilo s Savlom in Jonatanom; samo Savel in Jonatan, sin njegov, sta imela nekaj orožja.',
        23: 'In prednja straža Filistejcev se je pomeknila naprej do soteske pri Mikmasu.',
    },
    14: {
        1: 'In zgodi se nekega dne, da veli Jonatan, sin Savlov, mladeniču, ki mu je nosil orožje: Pridi, pojdiva tja k prednji straži Filistejcev, ki je na oni strani. A očetu svojemu ni tega povedal.',
        2: 'In Savel je stanoval ob zadnjem koncu Gibee pod granatovcem, ki je v Migronu; bilo pa je pri njem ljudstva okoli šeststo mož.',
        3: 'In Ahija, sin Ahituba, Ikabodovega brata, sina Pinehasa, sinu Elijevega, duhovnika Gospodovega v Silu, je nosil naramnik. In ljudstvo ni vedelo, da je Jonatan odšel.',
        4: 'Ob prelazu pa, koder je skušal Jonatan preiti k prednji straži Filistejcev, je bila rtasta skala na tej in rtasta skala na oni strani; ime prvi je bilo Bozez, drugi pa Sene.',
        5: 'En rt se vzpenja kakor steber na severu proti Mikmasu in drugi na jugu proti Gebi.',
        6: 'In Jonatan reče mladeniču, oprodi svojemu: Pridi, pojdiva na ono stran k prednji straži teh neobrezancev! Morebiti da bo Gospod delal za naju; zakaj Gospodu ni težko storiti rešitve po velikem ali majhnem številu.',
        7: 'Nato mu odgovori oproda njegov: Stóri vse, kar ti je v srcu; kreni kamorkoli, glej, jaz sem s teboj po tvojem srcu!',
        8: 'Jonatan torej veli: Glej, ko prideva na on kraj k tem možem in se jim prikaževa,',
        9: 'ako nama poreko: Stojta, dokler ne pridemo k vama! obstaneva na svojem mestu in ne pojdeva gori k njim.',
        10: 'Ako pa poreko: Pridita gori k nam! stopiva gori, zakaj Gospod jih je nama dal v roke. In to nama bodi znamenje.',
        11: 'Prikažeta se torej oba straži Filistejcev; in Filistejci reko: Glej, Hebrejci lezejo iz lukenj, kamor so se bili poskrili.',
        12: 'In možje, ki so stali na straži, ogovore Jonatana in oprodo njegovega, rekoč: Pridita gori k nam, da vama nekaj pokažemo! In Jonatan veli oprodi svojemu: Stopaj za menoj, zakaj Gospod jih je dal v roke Izraelu.',
        13: 'In Jonatan leze gori po rokah in po nogah, in oproda njegov za njim. In oni padajo pred Jonatanom, in njegov oproda jih pobija za njim.',
        14: 'Tako sta jih Jonatan in oproda njegov v tej prvi bitki pobila okoli dvajset mož kakor na polovici brazde na orali njive.',
        15: 'In strah je prišel v tabor na polju in med vse ljudstvo; tudi straže in plenilce je obšel strah, in zemlja se je tresla, kajti strah je bil od Boga.',
        16: 'In stražarji Savlovi v Gibei Benjaminovi so gledali, in glej, množica se razpršuje in bega semtertja.',
        17: 'Tedaj veli Savel ljudstvu, ki je bilo pri njem: Preštejte se in oglejte, kdo je izmed naših odšel! In ko so prešteli, glej, Jonatana in oprode njegovega ni bilo tam.',
        18: 'Nato veli Savel Ahiju: Prinesi sem skrinjo Gospodovo! Zakaj skrinja Gospodova je bila tisti čas s sinovi Izraelovimi.',
        19: 'In ko Savel še govori z duhovnikom, postane hrup v taboru Filistejcev večji in silnejši. In Savel reče duhovniku: Umakni roko svojo!',
        20: 'In Savel skliče vse ljudstvo, kar ga je bilo pri njem, in pohité tja v bitko, in glej, vsakega meč je sekal svojega bližnjega, in bila je velika zmešnjava.',
        21: 'Pa tudi Hebrejci, ki so bili prej pri Filistejcih in so iz okolice šli ž njimi gori v tabor, so se zdaj pridružili Izraelu, ki je bil pri Savlu in Jonatanu.',
        22: 'Takisto se vsi Izraelovi možje, ki so se bili poskrili na Efraimskem gorovju, ko slišijo, da Filistejci beže, pridružijo svojim v boju ter jih podijo.',
        23: 'Tako je rešil Gospod tisti dan Izraela; in bitka se je raztegnila do Betavena.',
        24: 'A možje Izraelovi so se preveč upehali tisti dan. Savel pa je zarotil vse ljudstvo, rekoč: Proklet bodi mož, ki bi kaj jedel do večera, da se maščujem nad sovražniki svojimi. Nihče torej iz ljudstva ni okusil kruha.',
        25: 'In vse ljudstvo je prišlo v gozd, in tam je bilo medu po tleh.',
        26: 'In ko je ljudstvo prišlo v gozd, glej, med se je cedil; ali nihče ga ni del z roko k ustom svojim, kajti ljudstvo se je balo tiste zakletve.',
        27: 'Jonatan pa ni bil slišal, ko je oče njegov zarotil ljudstvo; zato iztegne palico, ki jo je imel v roki, in njen konec pomoči v satovje medu in ga z roko poda k ustom svojim; in oči se mu razsvetijo.',
        28: 'Tedaj izpregovori eden iz ljudstva in reče: Oče tvoj je z ostro prisego zavezal ljudstvo, veleč: Proklet bodi mož, ki bi danes jedel kaj; in ljudstvo je bilo že utrujeno.',
        29: 'Nato reče Jonatan: V nesrečo je spravil oče moj deželo. Poglejte vendar, kako so se mi oči razsvetile, ker sem le malo okusil tega medu!',
        30: 'Koliko bolj, ako bi bilo ljudstvo svobodno jedlo od ropa svojih sovražnikov, ki ga je dobilo! Ali bi ne bil še večji poboj Filistejcev?',
        31: 'In pobijali so ta dan Filistejce od Mikmasa do Ajalona, dasi je bilo ljudstvo silno trudno.',
        32: 'Potem se ljudstvo loti ropa, in vzemo ovce in goveda in teleta in jih koljejo na tleh, in jih jedo s krvjo vred.',
        33: 'To pa oznanijo Savlu in reko: Glej, ljudstvo greši zoper Gospoda, ker jedo s krvjo vred! On veli: Spačeno ste delali! Privalite zdaj k meni velik kamen!',
        34: 'Še veli Savel: Razkropite se med ljudstvo in povejte jim, naj vsakdo pripelje svojega vola in ovco svojo sem k meni, in tu jih koljite in jejte, in ne grešite zoper Gospoda, jedoč s krvjo vred! Vse ljudstvo torej pripelje, vsak svoje živinče z roko svojo, po noči tja, in ondi jih koljejo.',
        35: 'In Savel zgradi oltar Gospodu; ta je bil prvi oltar, ki ga je postavil Gospodu.',
        36: 'In Savel reče: Spustímo se za Filistejci po noči in jih plenimo do jutranjega svita, in nihče izmed njih naj ne preostane! Odgovore: Stóri, karkoli se ti zdi prav. Ali duhovnik reče: Pristopimo sem k Bogu!',
        37: 'In Savel vpraša Boga: Ali naj grem doli za Filistejci? Hočeš jih li dati Izraelu v roke? A on mu ni odgovoril tisti dan.',
        38: 'In Savel veli: Naj pristopijo sem vsi poglavarji ljudstva, in zvedite ter poglejte, na kom je danes ta greh.',
        39: 'Zakaj, kakor res živi Gospod, ki rešuje Izraela, ako bi tudi bilo na Jonatanu, sinu mojem, mora umreti. A ni ga bilo med vsem ljudstvom, da bi mu odgovoril.',
        40: 'On pa reče vsemu Izraelu: Bodite vi na oni strani, jaz pa in sin moj Jonatan bodeva na tej strani. In ljudstvo reče Savlu: Stóri, kar se ti zdi prav!',
        41: 'Nato reče Savel Gospodu, Bogu Izraelovemu: Pokaži pravico! In zadeta sta bila Savel in Jonatan, ljudstvo pa je bilo prosto.',
        42: 'Savel reče: Vrzite kocko med menoj in Jonatanom, mojim sinom. In zadet je bil Jonatan.',
        43: 'In Savel reče Jonatanu: Povej mi, kaj si storil? In Jonatan mu pove in reče: Res sem okusil malo medu s koncem palice, ki sem jo imel v roki, in glej, moram umreti!',
        44: 'Savel pa reče: Bog mi stori to in ono, ako gotovo ne umreš, Jonatan!',
        45: 'Ali ljudstvo govori Savlu: Jonatan li naj umre, ki je storil to veliko rešitev v Izraelu? Nikakor ne! Kakor res Gospod živi, še las mu ne pade z glave na zemljo! zakaj z Bogom je delal danes. Tako je ljudstvo oprostilo Jonatana, da ni umrl.',
        46: 'Tedaj se je vrnil Savel in ni gonil Filistejcev, in Filistejci so odšli v svoj kraj.',
        47: 'Ko pa je bil Savel prejel kraljevanje nad Izraelom, se je bojeval zoper vse sovražnike svoje na vseh straneh, zoper Moabce, zoper sinove Amonove, zoper Edomce, zoper kralje v Zobi in zoper Filistejce; in kamorkoli se je obrnil, se je maščeval.',
        48: 'In vedel se je hrabro in porazil Amalekovce in je otel Izraela iz roke plenilcev.',
        49: 'Imel pa je Savel sinove: Jonatana, Išvija in Malhisuva. In dve hčeri njegovi sta se imenovali: prvenka Meraba in mlajša Mihala.',
        50: 'Ime Savlovi ženi pa je bilo Ahinoama, hči Ahimaazova. Poveljniku vojske njegove pa je bilo ime Abner, sin Nera, Savlovega strica.',
        51: 'Kis pa, oče Savlov, in Ner, oče Abnerjev, sta bila sinova Abielova.',
        52: 'In dokler je Savel živel, je bila trda vojska zoper Filistejce. Zato kjerkoli je Savel videl kakega junaškega in hrabrega moža, ga je vzel k sebi.',
    },
    15: {
        1: 'Samuel pa je govoril Savlu: Gospod me je poslal, da te pomazilim za kralja nad ljudstvom njegovim, nad Izraelom; sedaj torej poslušaj glas besed Gospodovih.',
        2: 'Tako pravi Gospod nad vojskami: Ozrl sem se na to, kar je Amalek storil Izraelu, kako mu je založil pot, ko je šel sem iz Egipta.',
        3: 'Pojdi torej in udari Amaleka ter s prokletjem pogubi vse, kar imajo; nič jim ne prizanašaj, temuč pomori može in žene, otroke in dojenčke, vole in ovce, velblode in osle.',
        4: 'Tedaj skliče Savel ljudstvo in ga prešteje v Telaimu: dvesto tisoč pešcev in deset tisoč mož iz Jude.',
        5: 'In Savel pride k mestu Amalekovcev in postavi zasedo v dolini.',
        6: 'In Savel sporoči Kenejcem: Pojdite, umaknite se, odpravite se izmed Amaleka, da vas ne potrebim ž njimi vred; kajti vi ste prijaznost storili vsem sinovom Izraelovim, ko so šli iz Egipta. Nato so se umeknili Kenejci izmed Amalekovcev.',
        7: 'In Savel udari Amalekovce od Havile tja do Sura, ki je Egiptu nasproti.',
        8: 'Agaga pa, kralja Amalekovcev, je ujel živega; a vse ljudstvo je kot prokleto pomoril z ostrino meča.',
        9: 'Toda Savel in ljudstvo je prizaneslo Agagu, in kar je bilo lepih ovac in goved in pitane živine in jagnjet in vsega, kar je bilo dobrega, niso hoteli kot prokleto pokončati; karkoli pa je bilo slabega in nevrednega, so pokončali kot prokleto.',
        10: 'Tedaj pride beseda Gospodova k Samuelu, govoreč:',
        11: 'Žal mi je, da sem postavil Savla za kralja; zakaj odvrnil se je, da ne bi šel za menoj, in ni izpolnil besed mojih. In razsrdi se Samuel in vpije h Gospodu vso noč.',
        12: 'In Samuel vstane zgodaj, da zjutraj sreča Savla. In sporočijo Samuelu: Savel je prišel v Karmel, in glej, postavil si je spomenik; potem je hodil okoli in šel naprej in stopil doli v Gilgal.',
        13: 'Ko Samuel dospe k Savlu, mu reče Savel: Blagoslovljen bodi od Gospoda; izvršil sem povelje Gospodovo.',
        14: 'Samuel odgovori: Kakovo je to torej beketanje ovac v mojih ušesih in mukanje volov, ki ga slišim?',
        15: 'Savel reče: Od Amalekovcev so jih pripeljali; zakaj ljudstvo je prizaneslo boljšim ovcam in volom, da naj se darujejo Gospodu, Bogu tvojemu; ostalo pa smo kot prokleto pokončali.',
        16: 'Tedaj reče Samuel Savlu: Postoj, da ti povem, kaj mi je govoril Gospod nocoj. On mu reče: Povej!',
        17: 'In Samuel pravi: Ni li tako: ko si bil majhen v svojih očeh, si bil postavljen za glavo rodovom Izraelovim? In Gospod te je pomazilil za kralja nad Izraelom.',
        18: 'In Gospod te je poslal na pot in rekel: Pojdi in kot proklete pogubi grešnike Amalekovce, in bojuj se ž njimi, dokler jih ne zatareš.',
        19: 'Zakaj nisi torej poslušal glasu Gospodovega, temuč si se lotil ropa in storil, kar je hudo v očeh Gospodovih?',
        20: 'Savel pa reče Samuelu: Saj sem slušal glas Gospodov in sem šel po potu, ki me je nanj poslal Gospod, in sem pripeljal Agaga, kralja Amalekovcev, Amalekovce pa sem pogubil kot proklete.',
        21: 'Ljudstvo pa je vzelo od ropa, ovac in volov, kar je bilo najboljše med prokletim, da naj se daruje. Gospodu, Bogu tvojemu, v Gilgalu.',
        22: 'Samuel pa reče: Ali so Gospodu toliko v veselje žgalne in klalne daritve, kakor da se posluša glas Gospodov? Glej, pokorščina je boljša, nego daritev, in poslušati je bolje nego prinašati tolstino ovnov.',
        23: 'Zakaj upor je kakor greh čaranja, in samovolja kakor malikovalstvo in podobočastje. Ker si pa zavrgel besedo Gospodovo, je tudi tebe Gospod zavrgel, da ne boš kralj.',
        24: 'In Savel reče Samuelu: Grešil sem, ker sem prestopil povelje Gospodovo in besede tvoje; zakaj bal sem se ljudstva in slušal njih glas.',
        25: 'Sedaj pa, prosim, odpusti mi greh moj in vrni se z mano, da molim Gospoda.',
        26: 'Samuel odgovori Savlu: Ne vrnem se s teboj; zakaj ti si zavrgel besedo Gospodovo, in Gospod je tebe zavrgel, da ne boš kralj Izraelu.',
        27: 'In Samuel se obrne, da gre proč; on pa popade konec njegovega plašča, da se je odtrgal.',
        28: 'Tedaj mu reče Samuel: Gospod je danes odtrgal kraljestvo Izraelovo od tebe in ga je dal bližnjiku tvojemu, ki je boljši nego ti.',
        29: 'Pa tudi Stanovitnik Izraelov ne laže in se ne kesa; ker on ni človek, da bi se kesal.',
        30: 'On pa reče: Grešil sem; a sedaj me spoštuj, prosim, pred starejšinami ljudstva mojega in pred Izraelom, in vrni se z mano, da molim Gospoda, Boga tvojega.',
        31: 'Vrne se torej Samuel za Savlom; in Savel je molil Gospoda.',
        32: 'Potem veli Samuel: Pripeljite sem k meni Agaga, kralja Amalekovcev! In Agag prikorači veselo k njemu. In Agag reče: Zares, grenkost smrti je minila!',
        33: 'A Samuel reče: Kakor je meč tvoj mnogim materam vzel otroke, tako bodi mati tvoja brez otrok med ženami! In Samuel je razsekal Agaga v kose pred Gospodom v Gilgalu.',
        34: 'Potem odide Samuel v Ramo; in Savel gre gori v hišo svojo v Gibei Savlovi.',
        35: 'In Samuel ni videl več Savla do dne smrti svoje; kajti Samuel je žaloval nad Savlom, ker je bilo Gospodu žal, da je postavil Savla za kralja Izraelu.',
    },
    16: {
        1: 'In Gospod reče Samuelu: Doklej boš žaloval nad Savlom, ker sem ga jaz zavrgel, da ne bo kralj Izraelu? Napolni rog svoj z oljem in pojdi, pošljem te k Jeseju Betlehemskemu; zakaj med njegovimi sinovi sem si ugledal kralja.',
        2: 'Samuel pa reče: Kako naj grem? Ako zve Savel, me umori. Gospod veli: Vzemi junico s seboj in reci: Prišel sem darovat Gospodu!',
        3: 'In povabi Jeseja k daritvi, in pokažem ti, kaj naj storiš; in pomazili mi njega, za katerega ti bom velel.',
        4: 'Samuel torej stori, kar je rekel Gospod, in pride v Betlehem. In mestni starejšine mu pridejo s trepetom naproti in reko: Je li tvoj prihod miren?',
        5: 'On odgovori: Miren; prišel sem darovat Gospodu. Posvetite se in pridite z menoj k daritvi. In posvetil je Jeseja in sinove njegove ter jih povabil k daritvi.',
        6: 'In ko pridejo noter, pogleda Eliaba in reče: Gotovo je maziljenec Gospodov pred Njim.',
        7: 'Gospod pa veli Samuelu: Ne glej lica njegovega, ne visokosti njegove postave, ker sem ga zavrgel: zakaj ne gledam, kar gleda človek. Človek namreč gleda, kar je pred očmi, Gospod pa gleda v srce.',
        8: 'Nato pokliče Jesej Abinadaba in mu veli iti pred Samuela. In on reče: Tega tudi ni Gospod izvolil.',
        9: 'In Jesej veli, naj pristopi Sama. A on reče: Tega tudi ni Gospod izbral.',
        10: 'Tako je velel Jesej sedmerim sinovom svojim iti pred Samuela. A Samuel reče: Gospod ni izvolil nobenega izmed teh.',
        11: 'Nato vpraša Samuel Jeseja: So li že dečki vsi? On odvrne: Še eden je, najmlajši, in glej, pase ovce! In Samuel veli Jeseju: Pošlji tja in ga pripelji, zakaj ne sedemo za mizo, dokler ne pride sem.',
        12: 'Pošlje torej, in ga privede noter. In bil je rdečkast in lepega obličja in zale postave. In Gospod veli: Vstani in ga pomazili, zakaj ta je.',
        13: 'Tedaj vzame Samuel rog z oljem in ga pomazili sredi bratov njegovih. In Duh Gospodov je prišel z močjo nad Davida od tega dne in poslej. In Samuel je vstal in šel v Ramo.',
        14: 'Duh Gospodov pa je šel od Savla, in hud duh od Gospoda ga je vznemirjal.',
        15: 'In Savlovi služabniki mu reko: Glej, prosim, hud duh od Boga te vznemirja.',
        16: 'Ukaži, gospod naš, služabnikom svojim, ki so pred teboj, naj ti poiščejo moža, ki zna dobro igrati na harfo; in kadar pride nate hudi duh od Boga, bo igral mož z roko svojo, in bolje ti bode.',
        17: 'In Savel veli služabnikom svojim: Ozrite se mi torej po možu, ki dobro zna na strune, ter mi ga pripeljite.',
        18: 'Nato odgovori eden iz mladeničev in reče: Glej, videl sem sina Jeseja Betlehemskega, ta zna dobro na strune in je hraber junak in vojščak ter pameten v govoru in lepe postave mož, in Gospod je ž njim.',
        19: 'Zato pošlje Savel sle k Jeseju in sporoči: Pošlji mi Davida, sina svojega, ki je pri ovcah.',
        20: 'Tedaj vzame Jesej osla in mu naloži kruha in meh vina in kozliča, in pošlje to Savlu po svojem sinu Davidu.',
        21: 'Tako je prišel David k Savlu, in stal je v službo pred njim, in silno se mu je priljubil in je postal njegov oproda.',
        22: 'In Savel pošlje k Jeseju in sporoči: Prosim, naj ostane David pred mano, zakaj našel je milost v mojih očeh.',
        23: 'In bilo je, kadar je tisti duh od Boga prišel nad Savla, da je David vzel harfo in udarjal z roko na strune, in Savlu se je polajšalo in mu je bilo bolje, in hudi duh je šel od njega.',
    },
    17: {
        1: 'Filistejci pa zbero vojske svoje na boj in se skupijo pri Soku, ki je Judovo, in se ušatorijo med Sokom in Azeko, v Efesdamimu.',
        2: 'Tudi Savel in možje Izraelovi se zbero in se utabore ob Hrastovi dolini, in se pripravljajo za boj zoper Filistejce.',
        3: 'In Filistejci so stali na gori po tej strani, Izraelci pa so stali na gori po oni strani, in dolina je bila med njimi.',
        4: 'In iz tabora Filistejcev stopi dvobojnik, po imenu Goliat, iz Gata, visok šest komolcev in dlan.',
        5: 'In je imel bronasto čelado na glavi in luskinast oklep na sebi, in teža oklepa njegovega je bila pet tisoč seklov brona.',
        6: 'In na nogah je imel bronaste škornje in bronast ščit na plečih;',
        7: 'in njegovo suličišče je bilo kakor tkalsko vratilo, in bodalo njegove sulice je imelo šeststo seklov železa; in tisti, ki mu je nosil ščit, je stopal pred njim.',
        8: 'In se ustopi in kliče proti vojnim vrstam Izraelovim in jim reče: Čemu ste se šli pripravljat na boj? Nisem li jaz Filistejec in vi hlapci Savlovi? Izvolite moža za sebe, naj pride sem doli k meni!',
        9: 'Ako se more boriti z menoj in me ubije, bodemo vam hlapci; ako pa ga jaz premorem in ubijem, bodete nam hlapci in nam morate služiti.',
        10: 'Še reče Filistejec: Danes sem spravil v sramoto vojne vrste Izraelove; dajte mi moža, da se skupaj bojujeva!',
        11: 'In ko Savel in vsi Izraelci slišijo te besede Filistejca, se prestrašijo in se silno bojé.',
        12: 'David pa je bil sin tistega Efratejca iz Betlehema na Judovem, ki mu je bilo ime Jesej in je imel osem sinov; in ta mož je bil že starec v Savlovih dnevih in prileten med možmi.',
        13: 'In trije starejši sinovi Jesejevi so bili šli za Savlom na vojsko; in imena treh sinov njegovih, ki so šli na vojsko, so bila: Eliab prvenec, in po njem Abinadab, drugi, in tretji Sama.',
        14: 'David pa je bil najmlajši. In ko so bili šli trije starejši za Savlom,',
        15: 'je šel zopet David od Savla past očeta svojega ovce v Betlehemu.',
        16: 'A Filistejec je prihajal zjutraj in na večer in se je kazal štirideset dni.',
        17: 'Tedaj veli Jesej Davidu, sinu svojemu: Vzemi za brate svoje to efo prepraženega zrnja in teh deset hlebov, in teci k bratom svojim v tabor.',
        18: 'In teh deset svežih sirov donesi poveljniku njih tisoča, in obišči svoje brate in poglej, ali se jim dobro godi, in prinesi znamenje od njih.',
        19: 'Savel pa in oni in vsi možje Izraelovi so bili v Hrastovi dolini, vojskujoč se s Filistejci.',
        20: 'David torej vstane zgodaj zjutraj in izroči ovce varuhu in vzame darila ter odrine, kakor mu je Jesej zapovedal, in pride do vozne zagrade; vojska pa, ki je ravnokar šla ven v boj, je zagnala bojni krik.',
        21: 'Kajti Izraelci so se razvrstili za boj in tudi Filistejci, vojne čete proti četam.',
        22: 'David pa pusti svoje stvari v roki čuvaja prtljage in teče v vojne vrste ter dospe in pozdravi svoje brate.',
        23: 'In ko govori ž njimi, glej, dvobojnik, Filistejec iz Gata, po imenu Goliat, pride iz vrst Filistejcev in govori kakor poprej; in David je slišal.',
        24: 'Vsi možje Izraelovi pa, videč tega moža, so bežali pred njim in se silno bali.',
        25: 'In možje Izraelovi pravijo: Ste li videli tega moža, ki je stopal sem gori? Res, da postavi na sramoto Izraela, je stopil gori proti nam. Zatorej kdor ga ubije, njega kralj silno obogati in mu da hčer svojo in svobodno naredi njegovega očeta hišo v Izraelu.',
        26: 'In David vpraša može, ki so stali okoli njega, rekoč: Kaj dobi mož, ki ubije tega Filistejca in sramote reši Izraela? Kdo je pač Filistejec, ta neobrezanec, da sme v sramoto spravljati živega Boga vojne vrste?',
        27: 'In ljudstvo mu odgovori kakor poprej, rekoč: To dobi mož, ki ga ubije.',
        28: 'Ali Eliab, najstarejši brat njegov, ga je slišal govoriti z možmi; in razvname se Eliabu jeza zoper Davida, in reče: Zakaj si prišel doli? In pri kom si pustil tistih malo ovac v puščavi? Dobro poznam tvojo prevzetnost in srca tvojega hudobnost! Kajti prišel si doli, da gledaš bitko.',
        29: 'David pa reče: Kaj sem storil zdaj? Ni li mi razloga za to?',
        30: 'In obrne se od njega proti drugemu in govori kakor poprej; in ljudstvo mu zopet odgovori kakor prvikrat.',
        31: 'In ko so slišali besede, ki jih je govoril David, jih povedo pred Savlom; in Savel pošlje ponj.',
        32: 'In David reče Savlu: Nikomur naj ne upade srčnost zaradi njega; hlapec tvoj pojde in se bo bojeval s tem Filistejcem.',
        33: 'A Savel reče Davidu: Ne moreš iti proti temu Filistejcu, da se bojuješ ž njim; zakaj ti si mladenič, a on je vojščak od mladosti svoje.',
        34: 'David odgovori Savlu: Hlapec tvoj je pasel ovce očeta svojega; in kadar je prišel lev ali medved in odnesel ovčico iz črede,',
        35: 'sem šel za njim in ga udaril, in sem jo otel iz žrela njegovega. In ako se je postavil zoper mene, sem ga popadel za brado in ga udaril in ubil.',
        36: 'I leva i medveda je ubil hlapec tvoj: bodi torej ta Filistejec, neobrezanec, kakor teh eden, zato ker je kidal sramoto na živega Boga vojne vrste.',
        37: 'Še reče David: Gospod, ki me je otel iz krempljev levu in medvedu, me otme iz tega Filistejca roke. In Savel veli Davidu: Pojdi, Gospod bodi s teboj!',
        38: 'In Savel obleče Davida v svoje oblačilo ter mu posadi bronasto čelado na glavo in ga obda z oklepom.',
        39: 'Potem si David pripaše njegov meč čez obleko in poskusi iti; kajti ni bil vajen temu. Pa reče David Savlu: Ne morem iti v tem, zakaj nisem se privadil. Sleče torej to David.',
        40: 'In vzame svojo palico v roko in si izbere pet gladkih kamenov iz potoka ter jih dene v pastirsko spravo, ki jo je imel, v torbo, in vzame pračo svojo v roko in gre proti Filistejcu.',
        41: 'Tudi Filistejec prikoraka in se približa Davidu, in mož, ki mu je nosil ščit, gre pred njim.',
        42: 'In ko se Filistejec ozre in ugleda Davida, ga zaničuje; zakaj bil je mladenček in rdečkast, pa lepega obraza.',
        43: 'In Filistejec reče Davidu: Sem li mar pes, da greš s palico k meni? In Filistejec preklinja Davida pri bogovih svojih;',
        44: 'in reče Davidu: Pridi k meni, in dam meso tvoje pticam pod nebom in zverem na polju.',
        45: 'Tedaj reče David Filistejcu: Ti greš k meni z mečem, s sulico in s kopjem, a jaz grem k tebi v imenu Gospoda nad vojskami, Boga vojnih vrst Izraelovih, ki si jih sramotil.',
        46: 'Današnji dan te Gospod izda v roko mojo, in udarim te in ti vzamem glavo, in dam danes trupla filistejske vojske pticam pod nebom in zverinam na zemlji; in vsa zemlja spozna, da je Bog v Izraelu.',
        47: 'In ves ta zbor spozna, da Gospod rešuje, a ne z mečem, ne s sulico; zakaj Gospodov je boj, in on vas da v roko našo!',
        48: 'In ko se je vzdignil Filistejec in šel bliže proti Davidu, pohiti David in teče k bojnim vrstam Filistejcu nasproti.',
        49: 'In David seže z roko v torbo in vzame iz nje kamen in ga zaluči ter zadene Filistejca v čelo; in kamen mu predere čelo, in pade z obrazom na zemljo.',
        50: 'Tako je David premogel Filistejca s pračo in s kamenom in ga je udaril in umoril; in ni bilo meča v roki Davidovi.',
        51: 'In David priteče in stopi na Filistejca, in zgrabi meč njegov in ga potegne iz nožnice, ter ga usmrti in mu ž njim odseka glavo. In ko Filistejci vidijo, da je njih junak mrtev, zbeže.',
        52: 'Možje Izraelovi in Judovi pa vstanejo in zaženo bojni krik in pode Filistejce tja do doline in do vrat v Ekron. In padali so ranjeni izmed Filistejcev po poti do Saraima, do Gata in do Ekrona.',
        53: 'In ko so sinovi Izraelovi bili pregnali Filistejce, so se vrnili in oplenili njih taborišče.',
        54: 'David pa je vzel glavo Filistejčevo in jo prinesel v Jeruzalem, njegovo orožje pa je zložil v šatoru svojem.',
        55: 'Ko pa je videl Savel Davida gredočega proti Filistejcu, reče Abnerju, poveljniku vojske: Abner, čigav sin je ta mladenič? Abner pa reče: Kakor res živi duša tvoja, o kralj, ne vem.',
        56: 'In kralj veli: Vprašaj torej, čigav sin je ta mladenič!',
        57: 'Ko se vrne David po uboju Filistejca, ga vzame Abner in ga pripelje pred Savla, ko je še držal glavo Filistejčevo v roki.',
        58: 'In Savel mu reče: Čigav sin si, mladenič? David odgovori: Sin sem tvojega hlapca, Jeseja Betlehemskega.',
    },
    18: {
        1: 'In ko konča pogovor s Savlom, se priklene duša Jonatanova duši Davidovi; in Jonatan ga je ljubil kakor svojo dušo.',
        2: 'In Savel ga vzame k sebi ta dan in mu ne dovoli, da se vrne domov k očetu.',
        3: 'Tedaj skleneta Jonatan in David zavezo, ker ga je ljubil Jonatan kakor svojo dušo.',
        4: 'In sleče vrhnjo suknjo, ki jo je imel na sebi, in jo da Davidu, pa tudi obleko svojo, celó meč svoj, lok in pas svoj.',
        5: 'In David je hodil, kamorkoli ga je Savel pošiljal, in v vsem je ravnal razumno; in Savel ga je postavil nad vojščaki, in vse ljudstvo si ga je priljubilo, pa tudi vsi služabniki Savlovi.',
        6: 'Zgodi se pa, ko so šli domov, ko se je David vračal od uboja Filistejca, da pripojejo in priplešejo kralju Savlu naproti žene iz vseh Izraelovih mest z veseljem, z bobnicami in citrami.',
        7: 'In žene odpevajo druga drugi med godbo, govoreč: Savel je pobil svoj tisoč, a David svojih deset tisoč!',
        8: 'Tedaj se Savel silno razsrdi in šteje za zlo to besedo; in reče: Davidu so dale deset tisoč, a meni le tisoč; samo še kraljestva mu je treba.',
        9: 'In Savel je grdo gledal Davida od tega dne in poslej.',
        10: 'In zgodi se drugi dan, da pride hud duh od Boga z močjo na Savla, da je razsajal sredi hiše svoje; David pa je igral na strune kakor vsak dan. In Savel je imel sulico v roki.',
        11: 'In Savel vrže sulico, meneč: Pribodem Davida k steni. David pa se mu izogne dvakrat.',
        12: 'In Savel se je bal Davida, zakaj Gospod je bil ž njim, Savla pa je bil zapustil.',
        13: 'Zato ga je Savel odpravil od sebe in ga je postavil za tisočnika svojega. In David je hodil ven in noter na čelu ljudstva',
        14: 'in je ravnal razumno na vseh potih svojih, in Gospod je bil ž njim.',
        15: 'In ko je Savel videl, da ravna jako razumno, ga je bilo strah Davida.',
        16: 'Ali ves Izrael in Juda je ljubil Davida, kajti hodil je ven in noter njim na čelu.',
        17: 'In Savel reče Davidu: Glej, dam ti hčer svojo starejšo, Merabo, za ženo; samo mi bodi hraber mož in vojskuj se v bojih Gospodovih. Rekel si je pa Savel: Naj ne bo roka moja zoper njega, ampak roka Filistejcev bodi zoper njega.',
        18: 'David pa odgovori Savlu: Kdo sem jaz in kakšno je moje življenje ali očeta mojega rodovina v Izraelu, da bi bil kraljev zet?',
        19: 'Toda ko pride čas, da bi se Meraba, hči Savlova, dala Davidu, je bila dana Adrielu Meholačanu za ženo.',
        20: 'A Mihala, hči Savlova, je ljubila Davida. To so povedali Savlu, in videlo se mu je prav.',
        21: 'Rekel si je namreč Savel: Dam mu jo, da mu bodi v zanko in da bodi roka Filistejcev zoper njega. Zato reče Savel Davidu: S to drugo mi danes postaneš zet.',
        22: 'In Savel ukaže hlapcem svojim: Govorite z Davidom na tihem in recite: Glej, kralj ti je blagovoljen in vsi služabniki njegovi te ljubijo; sedaj torej postani kraljev zet!',
        23: 'In hlapci Savlovi so govorili te besede Davidu pred ušesi. A David reče: Menite li, da je lahko v svaštvo stopiti s kraljem? Jaz sem vendar ubog in nizek človek!',
        24: 'In hlapci Savlovi mu zopet povedo, rekoč: Take besede je govoril David.',
        25: 'Savel pa reče: Tako povejte Davidu: Kralj ne želi nobene dote, ampak le sto sprednjih kožic Filistejcev, da se maščevanje izvrši nad kraljevimi sovražniki. Ali Savel je mislil, naj bi David poginil po roki Filistejcev.',
        26: 'In ko so hlapci njegovi oznanili Davidu te besede, se mu je zdelo dobro, da postane kraljev zet. In še se niso dopolnili določeni dnevi,',
        27: 'ko David vstane in odide, on in možje njegovi, in pobije od Filistejcev dvesto mož. In David prinese njih sprednje kožice, in jih izroče prav vse kralju, da bi bil kraljev zet. In Savel mu da Mihalo, hčer svojo, za ženo.',
        28: 'In Savel je videl in spoznaval, da je Gospod z Davidom; in Mihala, hči Savlova, ga je ljubila.',
        29: 'In Savel se je še bolj bal Davida, in bil mu je sovražen vse dni.',
        30: 'In ko so knezi Filistejcev prišli se bojevat, je David ravnal, kadarkoli so prišli, bolj razumno nego vsi služabniki Savlovi; zato je močno slovelo ime njegovo.',
    },
    19: {
        1: 'Savel pa je govoril Jonatanu, sinu svojemu, in vsem služabnikom svojim, da bi umorili Davida. Ali Jonatanu, sinu Savlovemu, je bil David zelo pogodu.',
        2: 'In Jonatan sporoči Davidu in reče: Savel, oče moj, ti streže po življenju; sedaj torej, prosim, pazi ob jutru in ostani na skrivnem in se skrij.',
        3: 'Jaz pa pojdem in bom stal zraven očeta svojega na polju, kjer bodeš, in govoril bom z očetom svojim zate; in kar bom videl, ti oznanim.',
        4: 'In Jonatan je govoril najboljše o Davidu Savlu, očetu svojemu, in mu je rekel: Ne pregreši se, kralj, nad hlapcem svojim Davidom; zakaj on ni storil greha zoper tebe, ampak zelo koristno je zate, kar je storil.',
        5: 'Kajti izpostavil je nevarnosti življenje svoje in ubil Filistejca, in Gospod je pripravil slavno zmago vsemu Izraelu. Videl si to in se veselil. Zakaj se torej hočeš pregrešiti nad nedolžno krvjo, da ubiješ Davida brez vzroka?',
        6: 'In Savel je poslušal glas Jonatanov in prisegel: Kakor res Gospod živi, ne sme biti umorjen!',
        7: 'In Jonatan pokliče Davida in mu pove vse te besede. In Jonatan pripelje Davida k Savlu, in bival je pred njim kakor poprej.',
        8: 'In bila je zopet vojna; in David gre in se bojuje s Filistejci in jih premaga v velikem poboju, in zbeže pred njim.',
        9: 'A hud duh od Gospoda je prišel nad Savla, ko je sedel v hiši svoji in držal sulico v roki, David pa je igral na strune z roko svojo.',
        10: 'In Savel je mislil pribosti Davida s sulico k steni, a on se mu umakne, in sulica obtiči v steni; David pa zbeži in se reši to noč.',
        11: 'Potem pošlje Savel sle k hiši Davidovi, da nanj pazijo in ga zjutraj umore.To oznani Davidu žena njegova Mihala, rekoč: Ako ne rešiš življenja svojega to noč, jutri boš mrtev.',
        12: 'In Mihala spusti Davida skozi okno, da gre in pobegne in se reši.',
        13: 'Mihala pa vzame domačega malika in ga položi v posteljo in mu dene ob glavo mrežasto čepico iz kozje dlake ter ga pokrije z odejo.',
        14: 'In ko Savel pošlje sle, da pripeljejo Davida, reče ona: Bolan je.',
        15: 'Zopet pošlje Savel sle, da ogledajo Davida, veleč: Prinesite mi ga sem gori v postelji, da ga umorim.',
        16: 'In ko stopijo sli noter, glej, malik je na postelji in mrežasta čepica iz kozine ob njegovi glavi!',
        17: 'In Savel reče Mihali: Zakaj si me tako prekanila in pustila neprijatelja mojega, da je pobegnil? Mihala pa odgovori Savlu: Dejal mi je: Pústi me, ali te umorim!',
        18: 'David torej pobegne in se reši; in ko pride k Samuelu v Ramo, mu pove vse, kar mu je storil Savel. In gre s Samuelom, in prebivala sta v Najotu.',
        19: 'In povedo Savlu, rekoč: Glej, David je v Najotu v Rami.',
        20: 'Savel pa pošlje sle, da zgrabijo Davida. Ko so pa videli zbor prorokov, kako prorokujejo, in Samuela, stoječega njim na čelu, pride duh Božji nad sle Savlove, in prorokujejo tudi oni.',
        21: 'Ko to sporoče Savlu, pošlje druge sle, pa prorokujejo tudi oni. Zopet pošlje Savel sle v tretjič, a tudi oni prorokujejo.',
        22: 'Nato gre še sam v Ramo, in pride k velikemu studencu, ki je v Seku, in vpraša in reče: Kje je Samuel in David? Nekdo odgovori: Glej, v Najotu sta v Rami.',
        23: 'In gre tja v Najot v Rami, in duh Božji pride nad njega, in spotoma prorokuje, dokler ne pride v Najot v Rami.',
        24: 'In tudi on sleče oblačilo svoje in tudi prorokuje pred Samuelom, in je padel in ležal slečen ves ta dan in vso noč. Odtod pravijo: Je li Savel tudi med proroki?',
    },
    20: {
        1: 'David pa pobegne iz Najota v Rami ter pride in govori z Jonatanom: Kaj sem storil? Kaj je krivica moja in kaj je greh moj vpričo očeta tvojega, da mi streže po življenju?',
        2: 'On pa mu reče: Bog ne daj! ne umrješ. Glej, oče moj ne stori ničesar, ne velikega, ne malega, da ne bi prej meni razodel. Zakaj bi mar to tajil pred mano oče moj? Tega ni.',
        3: 'In David še priseže in reče: Oče tvoj dobro ve, da sem našel milost v tvojih očeh, zato misli: Jonatan ne sme tega vedeti, ker bi ga bolelo! Pa zares, kakor Gospod živi in kakor živi duša tvoja, samo stopinja je med menoj in med smrtjo.',
        4: 'Jonatan pa reče Davidu: Storiti hočem zate, karkoli želi srce tvoje!',
        5: 'In David reče Jonatanu: Glej, jutri bo mlaj, ko bi moral sedeti pri mizi s kraljem. Toda pústi me, da se na polju skrijem do večera tretjega dne.',
        6: 'Ako me oče tvoj pogreši in vpraša, reci: David me je silno prosil, da sme pohiteti v Betlehem, mesto svoje, ker ondi je letna daritev za vso rodovino.',
        7: 'Ako poreče: Dobro! pomeni to mir za hlapca tvojega, – ako pa se razjezi, vedi, da je hudo sklenil pri sebi.',
        8: 'Zato izkaži milost hlapcu svojemu, ker si me uvedel v zavezo Gospodovo s seboj. Ako pa je kaka krivica na meni, ubij me sam, ker zakaj bi me vodil k očetu svojemu?',
        9: 'In Jonatan reče: Nič tega se ti ne bo zgodilo! Kajti ako bi jaz res zaznal, da je sklenil oče moj hudo spraviti nadte, bi li tebi ne sporočil?',
        10: 'Nato reče David Jonatanu: Kdo mi pove, ako ti oče tvoj kaj trdega odgovori?',
        11: 'Jonatan veli Davidu: Pojdi, idiva ven na polje! In šla sta skupaj na polje.',
        12: 'In Jonatan reče Davidu: Gospod, Bog Izraelov, bodi priča: ko bom zvedel jutri ob tem času ali tretjega dne, da je moj oče dobre volje proti Davidu, ako ne pošljem k tebi in ti tega ne razkrijem!',
        13: 'Gospod stóri to ali ono Jonatanu, ako ti ne razodenem, če bi bila volja očeta mojega storiti ti hudo; in pošljem te stran, da v miru odideš, in Gospod bodi s teboj, kakor je bil z očetom mojim.',
        14: 'Ti pa boš ne samo meni, dokler živim, izkazoval milost Gospodovo, da me ne usmrtiš,',
        15: 'ampak tudi hiši moji ne prikrati milosti svoje vekomaj, tudi ne, ko iztrebi Gospod sovražnike Davidove, vsakega s površja zemlje.',
        16: 'Tako je Jonatan storil zavezo s hišo Davidovo, rekoč: Gospod naj kaznuje sovražnike Davidove!',
        17: 'In Jonatan je velel Davidu še enkrat priseči pri ljubezni, ki jo je imel do njega; zakaj ljubil ga je kakor svojo dušo.',
        18: 'Nato reče Jonatan Davidu: Jutri bo mlaj, in pogrešali te bodo, ker sedež tvoj ostane prazen.',
        19: 'In tretji dan stopi hitro sem doli in pridi na mesto, kjer si se bil skril ob onem delavniku, in sedi blizu kamena Azela.',
        20: 'Jaz pa izstrelim tri pšice mimo njega, kakor da bi se vadil v tarčo streljati.',
        21: 'Pa pazi, pošljem dečka, veleč: Pojdi, išči pšice! Ako porečem dečku: Glej, pšice leže na tej strani za tabo, prinesi jih! – pridi, zakaj to pomeni mir tebi in nobene nevarnosti, kakor res Gospod živi.',
        22: 'Ako pa porečem dečku takole: Glej, pšice so pred teboj dalje! pojdi, zakaj Gospod te pošilja proč.',
        23: 'Za stvar pa, ki sva o njej govorila ti in jaz, glej, Gospod je priča med teboj in med menoj vekomaj!',
        24: 'David se je torej skril na polju. In ko pride mlaj, sede kralj za mizo k jedi.',
        25: 'In kralj je sedel na mestu svojem ob steni kakor navadno; in Jonatan vstane, da sede Abner zraven Savla; a Davidov sedež je bil prazen.',
        26: 'Toda Savel ni rekel ničesar ta dan, zakaj mislil je: Njemu se je kaj primerilo, morda ni čist; gotovo ni čist.',
        27: 'A drugi dan po mlaju, ko je bil Davidov sedež zopet prazen, reče Savel sinu svojemu Jonatanu: Zakaj ni prišel Jesejev sin k jedi, ne včeraj, ne danes?',
        28: 'In Jonatan odgovori Savlu: David me je silno prosil, da bi smel iti v Betlehem;',
        29: 'dejal je: Dovoli mi, prosim, zakaj rodovina naša opravlja daritev v mestu, in brat moj sam me je povabil; če sem torej našel milost v tvojih očeh, naj grem, prosim, da vidim brate svoje. Zato ni prišel k mizi kraljevi.',
        30: 'Tedaj se razvname srd Savlov zoper Jonatana in mu reče: Uporne popačenke sin! ali ne vem, da si izvolil sina Jesejevega na sramoto sebi in tudi materi svoji?',
        31: 'Zakaj dokler bo živel sin Jesejev na zemlji, ne bodeš utrjen, tudi tvoje kraljestvo ne. Zatorej pošlji ponj in ga pripelji k meni, zakaj mora umreti.',
        32: 'Jonatan odgovori svojemu očetu Savlu in mu reče: Zakaj bi moral umreti? kaj je storil?',
        33: 'A Savel mahne s sulico po njem, da bi ga prebodel. Tedaj spozna Jonatan, da je trdno sklenil oče njegov Davida umoriti.',
        34: 'In vstane Jonatan izza mize v goreči jezi, in ne okusi jedi tisti drugi dan meseca, zakaj žalilo se mu je Davida, ker ga je oče njegov tako onečastil.',
        35: 'Zjutraj pa odide Jonatan na polje na kraj, določen Davidu, in majhen deček ž njim.',
        36: 'In veli dečku: Teci in išči mi pšice, ki jih izstrelim! In ko deček teče, izstreli pšico, da je letela mimo njega.',
        37: 'In ko dospe deček na mesto, kamor je padla pšica, kliče Jonatan za dečkom in reče: Ni li pšica dalje pred teboj?',
        38: 'Še kliče Jonatan za dečkom: Hitro teci, ne stoj! In Jonatanov deček zbere pšice in se vrne h gospodu svojemu.',
        39: 'A deček ni vedel ničesar, samo Jonatan in David sta vedela, kaj to pomeni.',
        40: 'Nato izroči Jonatan hlapcu svojemu orožje in mu veli: Pojdi, nesi je v mesto.',
        41: 'Ko pa deček odide, vstane David iz svojega skrivališča ob južni strani in pade z obrazom na tla ter se trikrat pokloni; potem poljubita drug drugega in skupaj jočeta, a David najbolj.',
        42: 'In Jonatan reče Davidu: Pojdi v miru! Kar sva obadva prisegla v imenu Gospodovem, rekoč: Gospod bodi med menoj in teboj in med semenom mojim in semenom tvojim, to veljaj vekomaj! In David vstane ter odide; Jonatan pa se vrne v mesto.',
    },
    21: {
        1: 'In David dospe v Nob k Ahimeleku duhovniku. In Ahimelek pride s trepetom Davidu nasproti in mu reče: Zakaj si sam in nikogar ni s teboj?',
        2: 'David reče duhovniku Ahimeleku: Kralj mi je nekaj ukazal in mi rekel: Naj nihče ne ve, po kaj sem te poslal in kaj sem ti ukazal. Hlapcem pa sem naročil, naj pridejo na ta in ta kraj.',
        3: 'In sedaj, kaj imaš pri roki? daj mi pet hlebov kruha v roko ali karkoli imaš!',
        4: 'Duhovnik pa odgovori in reče: Vsakdanjega kruha nimam pri roki, ampak le sveti kruh; če so se le mladeniči zdržali žen.',
        5: 'In David odgovori duhovniku in mu reče: Ni bilo žene z nami včeraj, ne predvčerajšnjim, ko sem odhajal, in posode mladeničev so svete; in tisti je že nekako vsakdanji kruh, tem bolj ker je danes novi posvečen v posodah.',
        6: 'Tedaj mu da duhovnik svetega kruha, ker tam ni bilo drugega nego kruhi obličja, ki so jih jemali izpred Gospoda, da polože gorke kruhe v dan, ko so jih vzeli.',
        7: 'Bil pa je ondi tisti dan mož iz služabnikov Savlovih, ki se je tam mudil pred Gospodom, in ime mu je bilo Doeg Edomec, načelnik Savlovih pastirjev.',
        8: 'In David reče Ahimeleku: Nimaš li tu pri roki sulice ali meča? Zakaj nisem vzel s seboj ne meča, ne orožja svojega, ker je kraljeva reč zahtevala naglost.',
        9: 'Duhovnik odgovori: Meč Goliata Filistejca, ki si ga ubil v Hrastovi dolini, glej, je zavit v odevo za naramnikom; če hočeš tega, ga vzemi, ker tu ni drugega. In David reče: Ni mu enakega, daj mi ga!',
        10: 'In David vstane in pobegne tisti dan iz strahu pred Savlom, in pride k Ahisu, kralju v Gatu.',
        11: 'In služabniki Ahisovi mu reko: Ni li to David, kralj dežele? Ni li ta, ki so o njem v kolu odpevale druga drugi, govoreč: Savel je pobil svoj tisoč, a David svojih deset tisoč.',
        12: 'David pa, ko je premislil te besede v srcu, se silno zboji Ahisa, kralja v Gatu.',
        13: 'In premenil je svoje vedenje pred njimi, in je besnel v njih rokah in praskal po durih v vratih in sline cedil po bradi svoji.',
        14: 'Tedaj reče Ahis služabnikom svojim: Poglejte, vidite, da je ta mož blazen! Čemu ste mi ga privedli?',
        15: 'Imam li premalo norcev, da ste mi tegale pripeljali, da bi norel pred menoj? Ta li naj pride v hišo mojo?',
    },
    22: {
        1: 'David torej odrine odtod in pobegne v Adulamsko votlino. Ko to slišijo bratje njegovi in vsa družina očeta njegovega, pridejo tja doli k njemu.',
        2: 'In zbrali so se pri njem vsake vrste ljudje, kdorkoli je bil v stiski in kogar je pritiskal upnik in kdor je bil žalostnega srca, in on je postal njih poglavar; in bilo jih je pri njem okoli štiristo mož.',
        3: 'In odondod odide David v Micpo na Moabskem, in reče kralju Moabcev: Prosim, naj oče moj in mati moja prideta in bivata pri vas, dokler ne zvem, kaj Bog stori z menoj.',
        4: 'In pripeljal ju je pred kralja moabskega, in sta ostala pri njem vse dni, dokler je David bival na trdnjavi.',
        5: 'A prorok Gad reče Davidu: Ne ostani na tej trdnjavi, vstani in pojdi v deželo Judovo. Tedaj odide David in pride v gozd pri Haretu.',
        6: 'In Savel je čul, da so zvedeli za Davida in za može, ki so bili ž njim. Savel pa je sedel v Gibei, pod tamarisko na višavi, v roki držeč sulico, in vsi hlapci njegovi so stali pred njim.',
        7: 'In reče Savel vsem hlapcem svojim, pri njem stoječim: Čujte vendar, Benjaminci! Ali vam da vsakemu sin Jesejev njiv in vinogradov? Postavi li vas vse za poveljnike čez tisoč in poveljnike čez sto?',
        8: 'Da ste se vsi zavezali zoper mene in ga ni, ki bi mi povedal, ko se moj sin veže s sinom Jesejevim? In ni ga med vami, ki bi mu bilo žal zaradi mene ali ki bi mi razodel, da je moj sin obudil mojega hlapca zoper mene, da preži name, kakor se danes vidi!',
        9: 'Nato odgovori Doeg Edomec, ki je stal poleg Savlovih hlapcev, in reče: Videl sem sina Jesejevega, da je prišel v Nob k Ahimeleku, sinu Ahitubovemu.',
        10: 'In on je zanj vprašal Gospoda in mu je dal živeža in meč Goliata Filistejca.',
        11: 'Tedaj pošlje kralj, da pokličejo Ahimeleka duhovnika, sina Ahitubovega, in vso očeta njegovega družino, duhovnike, ki so bili v Nobu; in vsi pridejo pred kralja.',
        12: 'In Savel veli: Čuj zdaj, sin Ahitubov! On odgovori: Glej, tu sem, gospod moj!',
        13: 'In Savel mu reče: Za kaj sta se zavezala zoper mene, ti in sin Jesejev, da si mu dal kruha in meč in si zanj vprašal Boga, da se vzdigne zoper mene, prežeč name, kakor se danes vidi?',
        14: 'Nato odgovori Ahimelek kralju in reče: In kdo je med vsemi služabniki tvojimi tako zvest kakor David, ki je kraljev zet in hodi v tvoje svetovalstvo in je spoštovan v hiši tvoji?',
        15: 'Ali sem šele danes zanj začel vpraševati Boga? To ne bodi na meni! Kralj naj ne prisoja kaj takega hlapcu svojemu, ne vsej očeta mojega družini, zakaj hlapec tvoj ne ve nič tega, ne malega, ne velikega.',
        16: 'Toda kralj reče: Gotovo umreš, Ahimelek, ti in vsa očeta tvojega družina!',
        17: 'In kralj veli stražarjem, ki so stali pri njem: Obrnite se in pobijte duhovnike Gospodove! Zakaj njih roka je tudi z Davidom, ker so vedeli, da beži, in mi niso naznanili. Ali kraljevi hlapci niso hoteli rok iztegniti na duhovnike Gospodove, da jih ubijejo.',
        18: 'In kralj veli Doegu: Obrni se ti in udari duhovnike! In Doeg Edomec se obrne in udari duhovnike, in je pobil tisti dan petinosemdeset mož, ki so nosili platneni naramnik.',
        19: 'In Nob, mesto duhovnikov, je udaril z ostrino meča, može in žene, otroke in dojence, goved in osle in ovce z ostrino meča.',
        20: 'Le eden sinov Ahimeleka, sina Ahitubovega, po imenu Abiatar, se je rešil, bežeč za Davidom.',
        21: 'In Abiatar je oznanil Davidu, da je Savel pomoril duhovnike Gospodove.',
        22: 'David pa reče Abiatarju: Vedel sem tisti dan, ko je bil ondi Doeg Edomec, da gotovo oznani Savlu; jaz sem provzročil smrt vseh oseb iz očeta tvojega hiše.',
        23: 'Ostani pri meni in se ne boj! Zakaj kdor meni streže po življenju, streže tebi po življenju, in pri meni boš dobro obvarovan.',
    },
    23: {
        1: 'Sporoče pa Davidu: Glej, Filistejci se vojskujejo zoper Keilo in plenijo gumna.',
        2: 'Tedaj vpraša David Gospoda, rekoč: Ali naj grem in udarim te Filistejce? In Gospod veli Davidu: Pojdi in udari Filistejce in reši Keilo.',
        3: 'A možje Davidovi mu reko: Glej, strah nas je tu na Judovem; koliko bolj, ako pojdemo h Keili proti vojskam Filistejcev?',
        4: 'Tedaj vpraša David še enkrat Gospoda. In Gospod mu odgovori in reče: Vstani, pojdi doli v Keilo, kajti dam ti Filistejce v roko.',
        5: 'David torej gre z možmi svojimi proti Keili in se bojuje s Filistejci, in razžene njih živino ter jih porazi v velikem poboju. Tako je David rešil prebivalce v Keili.',
        6: 'Ko pa je bežal Abiatar, sin Ahimelekov, k Davidu proti Keili, je prišel doli z naramnikom v roki svoji.',
        7: 'Tedaj sporoče Savlu, da je David prišel v Keilo. In Savel reče: Bog ga je dal v roko mojo, kajti zaprt je, ko je prišel v mesto, ki ima vrata in zapahe.',
        8: 'In Savel skliče vse ljudstvo v boj, da gredo doli proti Keili oblegat Davida in može njegove.',
        9: 'Ko pa David zazna, da mu Savel snuje nesrečo, veli Abiatarju duhovniku: Prinesi sem naramnik!',
        10: 'In David reče: O Gospod, Bog Izraelov, hlapec tvoj je zvedel za gotovo, da namerava Savel priti v Keilo, da bi pogubil mesto zaradi mene.',
        11: 'Me li bodo meščani v Keili izročili njemu? In pride li Savel doli, kakor je slišal hlapec tvoj? Gospod, Bog Izraelov, naznani, prosim, hlapcu svojemu! In Gospod reče: Pride doli.',
        12: 'Nato reče David: Izdado li meščani v Keili mene in može moje Savlu v roke? In Gospod odgovori: Izdado.',
        13: 'Tedaj vstane David in mož njegovih okoli šeststo, in uidejo iz Keile in gredo, kamorkoli so mogli iti. In ko sporoče Savlu, da je David pobegnil iz Keile, se neha tja pripravljati.',
        14: 'David pa je bival v puščavi na trdnjavah in se je mudil na gorovju v Zifski puščavi. In Savel ga je iskal vse dni, a Bog mu ga ni izdal v roke.',
        15: 'Ko pa David zve, da je šel Savel streč mu po življenju, je bil David v Zifski puščavi v logu.',
        16: 'In Jonatan, sin Savlov, vstane in gre k Davidu v log in mu pokrepča roko v Bogu.',
        17: 'In mu reče: Ne boj se, zakaj roka Savla, očeta mojega, te ne zaloti, in kraljeval boš nad Izraelom, in jaz bodem prvi pri tebi: to tudi ve Savel, oče moj.',
        18: 'In oba sta sklenila zavezo pred Gospodom. In David je ostal v logu, a Jonatan je šel domov.',
        19: 'Potem pridejo Zifovci k Savlu gori v Gibeo in reko: Ne skriva li se David pri nas po trdnjavah v logu, na hribu Hahili, ki je ob južni strani puščave?',
        20: 'Sedaj torej, o kralj, pridi doli po vsej želji srca svojega, in na nas je, da ga izdamo kralju v roko.',
        21: 'In Savel reče: Blagoslovljeni bodite od Gospoda, da ste se me usmilili!',
        22: 'Pojdite tja, prosim, in še bolje se prepričajte, in zvedite in preglejte mesto, kjer ima brlog, in kdo ga je ondi videl; zakaj povedali so mi, da je zelo zvit.',
        23: 'Oglejte torej in pozvedite vsa zakotja, po katerih se skriva, in spet pridite k meni, kadar bodete gotovi, in pojdem z vami. Ako je v deželi, ga hočem iskati med vsemi tisoči Judovimi!',
        24: 'In vstanejo in gredo v Zif pred Savlom. David pa in možje njegovi so bili v Maonski puščavi, v nižini ob južni strani puščave.',
        25: 'In Savel odrine z možmi svojimi ga iskat. A Davidu se sporoči to, in stopi po skali doli in ostane v Maonski puščavi. In ko to sliši Savel, pohiti za Davidom v Maonsko puščavo.',
        26: 'In Savel je šel po tej strani gore, David in možje njegovi pa po oni strani gore. In David je hitel, da uide izpred Savla, a Savel in moštvo njegovo je obdalo Davida in može njegove, da bi jih ujeli.',
        27: 'V tem dospe sel k Savlu in reče: Hiti in pridi, zakaj Filistejci so napadli deželo!',
        28: 'Savel se torej obrne, da ne bi podil Davida, in se napravi zoper Filistejce. Zato se imenuje tisto mesto Sela-hamah-lekot.',
        29: 'David pa je šel od ondod gori in je bival v trdnjavah v Engediju.',
    },
    24: {
        1: 'In ko se Savel vrne od Filistejcev, mu sporoče, rekoč: Glej, David je v Engedijski puščavi.',
        2: 'Tedaj vzame Savel tri tisoč izbranih mož iz vsega Izraela in odrine iskat Davida po skalah divjih koz.',
        3: 'In pride k ovčjim stanom pri poti, in ondi je bila votlina, in Savel stopi vanjo na potrebo. David in možje njegovi pa so sedeli zadaj v votlini.',
        4: 'In možje Davidovi mu reko: Glej, to je dan, o katerem ti je govoril Gospod: Glej, jaz ti dam sovražnika tvojega v roko, in storiš mu, kakor se ti bo zdelo prav. Tedaj vstane David in tiho odreže rob Savlovega plašča.',
        5: 'Potem pa očita Davidu srce njegovo, ker je odrezal Savlu rob plašča,',
        6: 'in reče možem svojim: Gospod me obvaruj, da ne storim te stvari gospodu svojemu, maziljencu Gospodovemu, da bi iztegnil roko zoper njega; kajti on je maziljenec Gospodov!',
        7: 'Tako je David ukrotil može svoje s temi besedami in jim ni dovolil vzdigniti se zoper Savla. In Savel vstane iz votline in gre svojim potom.',
        8: 'Potem vstane tudi David in stopi iz votline in kliče za Savlom, rekoč: Gospod moj, kralj! In ko se ozre Savel, se nagne David z obličjem k tlom in se prikloni.',
        9: 'In David reče Savlu: Zakaj poslušaš besede ljudi, ki pravijo, da išče David nesreče tvoje?',
        10: 'Glej, danes so videle oči tvoje, da te je Gospod dal v votlini meni v roko, in bilo mi je rečeno, naj te umorim; ali oko moje ti je zaneslo, in dejal sem: Ne iztegnem roke zoper gospoda svojega, kajti on je maziljenec Gospodov.',
        11: 'Marveč glej, oče moj, glej rob plašča svojega v roki moji, da te res nisem hotel umoriti, ko sem odrezal rob plašča tvojega. Spoznaj in poglej, da nič hudega ni v roki moji, ne nobenega prestopka, in da nisem grešil zoper tebe, a ti mi strežeš po življenju, da bi mi ga vzel.',
        12: 'Gospod bo sodnik med menoj in teboj in me bo nad tabo maščeval, ali roka moja se te ne dotakne.',
        13: 'Kakor pravi pregovor starih: Od krivičnih prihaja krivičnost; zato se te roka moja ne dotakne.',
        14: 'Za kom se je gnal Izraelov kralj? Koga preganjaš? mrtvega psa? bolho edino?',
        15: 'Gospod torej bodi sodnik in razsódi med menoj in teboj in oglej in prevzemi pravdo mojo in me oprosti roke tvoje.',
        16: 'In ko David konča govor svoj Savlu, reče Savel: Ni li to tvoj glas, sin moj David? In Savel povzdigne glas svoj ter joka.',
        17: 'In reče Davidu: Pravičnejši si od mene: kajti ti si mi izkazal dobro, jaz pa sem ti povrnil hudo.',
        18: 'In ti si danes pokazal, da si mi dobroto storil: zakaj ko me je Gospod izdal tebi v roko, me vendar nisi umoril.',
        19: 'Saj če kdo zaloti sovražnika svojega, ali ga pusti mirnim potom? Zato ti Gospod poplačaj z dobrim, kar si mi storil ta dan.',
        20: 'In sedaj, glej, vem, da bodeš gotovo kralj ter da bo kraljestvo Izraelovo trdno stalo v tvoji roki.',
        21: 'Prisezi mi torej zdaj pri Gospodu, da ne zatareš semena mojega po meni in da ne potrebiš imena mojega iz očeta mojega hiše.',
        22: 'In David priseže Savlu. Tedaj odide Savel domov, David in možje njegovi pa se spravijo gori v trdnjavo.',
    },
    25: {
        1: 'In Samuel je umrl, in ves Izrael se je zbral in žaloval po njem. In so ga pokopali v hiši njegovi v Rami. David pa vstane in gre doli v Paransko puščavo.',
        2: 'Bil pa je v Maonu mož, ki je imel posestvo svoje v Karmelu, in ta mož je bil silno velik in je imel tri tisoč ovac in tisoč koz. In je strigel ovce svoje v Karmelu.',
        3: 'Ime pa je bilo tistemu množu Nabal in ime ženi njegovi Abigaila; in žena je bila jako razumna in lepega lica, a mož neotesanec in hudoben v svojih dejanjih; bil pa je iz družine Kalebove.',
        4: 'Ko pa je David slišal v puščavi, da striže Nabal ovce svoje,',
        5: 'pošlje deset mladeničev in jim reče: Pojdite gori v Karmel, in ko pridete k Nabalu, ga prijazno pozdravite v mojem imenu',
        6: 'in recite: Sreča! Mir bodi tebi in hiši tvoji mir in vsemu, kar imaš, mir!',
        7: 'Slišal sem, da imaš strižce. Pastirji pa, kar jih imaš, so bili pri nas, in nismo jim bili nadležni, tudi niso ničesar pogrešali vse dni, dokler so bili ob Karmelu.',
        8: 'Vprašaj mladeniče svoje, in ti bodo povedali. Zato naj najdejo moji mladeniči milost v tvojih očeh; zakaj prišli smo na dober dan. Daj, prosim, hlapcem svojim in sinu svojemu Davidu, kar ti pride v roko.',
        9: 'In ko pridejo mladeniči Davidovi, govore Nabalu po vseh teh besedah v imenu Davidovem, in umolknejo.',
        10: 'Nabal pa odgovori hlapcem Davidovim in reče: Kdo je David? in kdo je Jesejev sin? Dandanes je čimdalje več hlapcev, ki uhajajo svojim gospodarjem!',
        11: 'Ali naj vzamem kruh svoj in vodo svojo in meso živinčet, ki sem jih zaklal za strižce svoje, in naj to dam ljudem, za katere ne vem, od kod so?',
        12: 'Tedaj se obrnejo mladeniči Davidovi na svojo pot. In pridejo nazaj k njemu in mu povedo vse te besede.',
        13: 'In David veli možem svojim: Vsak si opaši meč! In vsi se opašejo z mečem, tudi David opaše svoj meč. In je šlo za njim gori blizu štiristo mož, dvesto jih je pa ostalo pri prtljagi.',
        14: 'Eden mladeničev pa oznani Abigaili, ženi Nabalovi, rekoč: Glej, David je poslal sle iz puščave, da pozdravijo našega gospodarja, a on je kriče planil nanje.',
        15: 'Toda tisti možje so nam bili dosti v prospeh, in žalega se nam ni nič zgodilo, tudi nismo ničesar pogrešali, dokler smo ž njimi občevali, ko smo bili na polju;',
        16: 'bili so nam kakor zidovje po noči in po dnevi, dokler smo pri njih pasli ovce.',
        17: 'Zdaj torej pazi in premisli, kaj ti je storiti; zakaj hudo je sklenjeno zoper gospodarja našega in zoper vso hišo njegovo. On pa je tak otrok Belijalov, da ne more nihče ž njim govoriti.',
        18: 'Tedaj pohiti Abigaila, in vzame dvesto hlebov in dva mehova vina in pet pripravljenih ovac in pet meric opraženega zrnja in sto posušenih grozdov in dvesto kep smokev, in naloži to na osle.',
        19: 'In veli mladeničem svojim: Pojdite pred menoj, glejte, jaz pridem za vami! A možu svojemu Nabalu ni povedala nič.',
        20: 'In ko sede na osla in jezdi doli po gorskem ovinku, pridejo ji nasproti David in možje njegovi, in jih sreča.',
        21: 'David pa je rekel: Res sem zastonj varoval vse, kar je njegovega, v puščavi, da se ni ničesar pogrešilo tega, kar ima; še hudo mi je povrnil za dobro.',
        22: 'To naj stori Bog sovražnikom Davidovim in to naj doda, ako pustim od vsega, kar je njegovega, do jutranjega svita le enega moškega.',
        23: 'In ko vidi Abigaila Davida, spusti se hitro z osla in pade pred Davidom na obraz in se prikloni do tal.',
        24: 'In pade k nogam njegovim in reče: Na meni, gospod moj, na meni bodi ta pregreha, in dovoli, prosim, dekli svoji govoriti v ušesa tvoja, in čuj dekle svoje besede!',
        25: 'Ne oziraj se, prosim, gospod moj, na tistega moža Belijalovega, na Nabala; zakaj kakršno je ime njegovo, takšen je on sam: Nabal mu je ime, in brezumnost je pri njem. Jaz pa, dekla tvoja, nisem videla mladeničev gospoda svojega, ki si jih poslal.',
        26: 'Zdaj pa, gospod moj, kakor res živi Gospod in živi duša tvoja: Gospod ti je zabranil, da nisi prišel prelivat krvi in se nisi maščeval z lastno roko. Naj torej bodo kakor Nabal sovražniki tvoji in kateri žele nesreče gospodu mojemu.',
        27: 'Tu je darilo, ki ga je služabnica tvoja prinesla gospodu svojemu; daj ga mladeničem, ki hodijo za gospodom mojim.',
        28: 'Odpusti, prosim, dekli svoji prestopek; zakaj Gospod bo gotovo ustanovil trdno hišo gospodu mojemu, ker gospod moj se vojskuje v bojih Gospodovih, in nič hudega se ni našlo na tebi, odkar živiš.',
        29: 'In ako bi se vzdignil človek, da te preganja in ti streže po življenju, gospoda mojega duša bode zvezana v zvezi živečih pri Gospodu, Bogu tvojem; a dušo sovražnikov tvojih naj zaluči kakor s prače.',
        30: 'In kadar Gospod stori gospodu mojemu po vsem dobrem, kar ti je obljubil, in ti zapove, da bodi vojvoda Izraelu,',
        31: 'ti tega ne bode žal, tudi srce ti tega ne bo očitalo, da nisi prelil krvi brez razloga in da ni samega sebe maščeval gospod moj. In ko Gospod stori dobro gospodu mojemu, spomni se dekle svoje.',
        32: 'Nato reče David Abigaili: Hvaljen bodi Gospod, Bog Izraelov, ki te je poslal danes meni naproti!',
        33: 'In blagoslovljena bodi razumnost tvoja in ti bodi blagoslovljena, da si me danes zadržala, da nisem šel prelivat krvi in se maščevat z lastno roko.',
        34: 'Zakaj v resnici, kakor res živi Gospod, Bog Izraelov, ki mi je ubranil, da ti nisem storil žalega, ako bi ne bila hitro prišla naproti, gotovo bi ne bil ostal Nabalu do jutranjega svita ne eden moški!',
        35: 'David torej sprejme iz roke njene, kar mu je prinesla, in ji reče: Pojdi v miru gori v hišo svojo! Glej, slišal sem glas tvoj in se ozrl na tvojo osebo!',
        36: 'In Abigaila pride k Nabalu. In glej, pripravil je v hiši svoji gostijo, kakor kraljevo gostijo, in srce Nabalovo je bilo veselo v njem, zakaj bil je jako pijan. Zato mu ona ničesar ne pove, ne malega, ne velikega, do jutranjega svita.',
        37: 'Ko pa se je zdanilo in se je Nabalu izkadilo vino, mu pove žena njegova te reči. In srce mu je v životu omrtvelo, in bil je kakor kamen.',
        38: 'In kakih deset dni pozneje udari Gospod Nabala, da je umrl.',
        39: 'In ko David zasliši, da je Nabal mrtev, reče: Hvaljen bodi Gospod, ki je prevzel pravdo mojo za sramotenje Nabalovo in je zadržal hlapca svojega, da ni storil hudega; in hudobnost Nabalovo mu je povrnil na glavo! In David pošlje in veli govoriti z Abigailo, da bi si jo vzel za ženo.',
        40: 'In ko pridejo hlapci Davidovi k Abigaili v Karmel, jo ogovore in reko: David nas je poslal k tebi, da bi te vzel za ženo.',
        41: 'Ona vstane in se prikloni z obličjem do tal in reče: Glej, tu je dekla tvoja, da bode služkinja in da umiva noge gospodarja svojega hlapcem!',
        42: 'In Abigaila hitro vstane in sede na osla in za njo gre pet njenih dekel, in je šla za sli Davidovimi in mu je postala žena.',
        43: 'Tudi Ahinoamo iz Jezreela je vzel David za ženo. Tako sta bili obedve ženi Davidovi.',
        44: 'Savel pa je bil dal Mihalo, hčer svojo, ženo Davidovo, Faltimu, sinu Laisovemu, iz Galima.',
    },
    26: {
        1: 'Zifovci pa pridejo k Savlu v Gibeo in reko: Ali se ne skriva David na hribu Hahili, ki je pred puščavo?',
        2: 'Tedaj se vzdigne Savel in gre doli v Zifsko puščavo in ž njim tri tisoč izbranih mož iz Izraela, da iščejo Davida v puščavi pri Zifu.',
        3: 'In Savel se je ušatoril na hribu Hahili, ki je pred puščavo, ob poti. Ali David je ostal v puščavi, in ko vidi, da je Savel prišel za njim v puščavo,',
        4: 'pošlje oglednike in zve, da je Savel že gotovo prišel.',
        5: 'In David vstane ter pride na mesto, kjer je Savel razpel šatore, in si ogleda kraj, kjer je ležal Savel in Abner, sin Nerov, poveljnik vojske njegove; in Savel je ležal sredi tabora za vozovi in moštvo je imelo šatore okrog njega.',
        6: 'Tedaj izpregovori David in reče Ahimeleku Hetejcu in Abisaju, sinu Zervijinemu, bratu Joabovemu: Kdo pojde z menoj doli k Savlu v tabor? In Abisaj reče: Jaz pojdem s teboj.',
        7: 'Prideta torej David in Abisaj k ljudstvu po noči. In glej, Savel je ležal speč sredi tabora za vozovi in sulica njegova je bila zabodena v zemljo pri glavi njegovi, Abner in ljudstvo pa je ležalo kroginkrog njega.',
        8: 'Tedaj reče Abisaj Davidu: Bog ti je danes izdal sovražnika tvojega v roko. Sedaj pa naj ga, prosim, zabodem s sulico v zemljo z enim mahljajem, da v drugič ne bo treba.',
        9: 'A David reče Abisaju: Ne umori ga! Kajti kdo bi smel iztegniti roko zoper maziljenca Gospodovega, pa ostati brez kazni?',
        10: 'Še reče David: Kakor res Gospod živi, ako se ne zgodi, da ga Gospod udari ali pride dan njegov, da umrje, ali da pojde v boj in pogine,',
        11: 'mene Gospod obvaruj, da ne iztegnem roke na maziljenca Gospodovega! Sedaj pa vzemi, prosim, sulico, ki je pri glavi njegovi, in vrč vode, pa pojdiva!',
        12: 'Tako vzame David sulico in vrč vode od glave Savlove, in odideta; in nihče ju ne vidi, niti opazi, tudi se nihče ne prebudi, temuč so vsi spali, zakaj prišlo je nanje trdno spanje od Gospoda.',
        13: 'Ko pa preide David na nasprotno stran, stopi na vrh hriba oddaleč, da je bila precejšnja razdalja med njimi;',
        14: 'in David zavpije proti ljudstvu in proti Abnerju, sinu Nerovemu, rekoč: Ne odgovoriš li, Abner? Tedaj odgovori Abner in reče: Kdo si ti, ki vpiješ proti kralju?',
        15: 'In David reče Abnerju: Ali nisi mož? in kdo je tebi enak v Izraelu? Zakaj torej nisi stražil gospoda svojega, kralja? Prišel je namreč nekdo iz ljudstva noter, da umori kralja, gospoda tvojega!',
        16: 'To pa ni lepo, kar si storil. Kakor res Gospod živi, smrt ste zaslužili, ker niste stražili gospoda svojega, maziljenca Gospodovega. Sedaj pa, poglej, kje je kraljeva sulica in vrč vode, ki ju je imel pri glavi?',
        17: 'V tem spozna Savel glas Davidov in reče: Ni li tvoj glas, sin moj David? In David odvrne: Moj glas, o gospod moj, kralj!',
        18: 'Dalje reče: Zakaj tako preganja gospod moj hlapca svojega? Ker kaj sem storil? in kaj je hudega v roki moji?',
        19: 'Sedaj pa poslušaj, prosim, gospod moj, kralj, besede hlapca svojega. Ako te Gospod draži zoper mene, naj se pomiri z daritvijo; ako pa to provzročajo otroci človeški, naj bodo prokleti pred Gospodom, ker so me spodili ta čas, da ne bi imel deleštva v dediščini Gospodovi, rekoč: Pojdi, služi drugim bogovom!',
        20: 'Sedaj torej, naj se ne prelije moja kri na zemljo, daleč od obličja Gospodovega; zakaj kralj Izraelov je šel iskat bolho edino, kakor če kdo lovi jerebico po planinah.',
        21: 'Tedaj reče Savel: Grešil sem. Vrni se, sin moj David, zakaj ne storim ti več nobene žali, ker je drago bilo danes življenje moje v tvojih očeh; glej, nespametno sem ravnal in prehudo se motil.',
        22: 'David odgovori in reče: Glej, tu je sulica kraljeva, naj pride eden mladeničev sem ter jo odnese.',
        23: 'Gospod pa povrne vsakemu po pravičnosti in zvestobi njegovi; zakaj Gospod te je danes dal meni v roko, toda nisem hotel iztegniti roke zoper maziljenca Gospodovega.',
        24: 'In glej, kakor je bilo danes dragoceno življenje tvoje v mojih očeh, tako bo življenje moje dragoceno v očeh Gospodovih, in on me otme iz vsake stiske.',
        25: 'Nato reče Savel Davidu: Blagoslovljen bodi, sin moj David! Ti izvršiš veliko in gotovo zmagaš. In David je šel svojim potom, Savel pa se je vrnil v svoj kraj.',
    },
    27: {
        1: 'David pa reče v srcu svojem: Nekega dne pa vendar poginem pod roko Savlovo. Najbolje zame, da naglo zbežim v deželo Filistejcev, in Savel me neha iskati po vseh pokrajinah Izraelovih, in tako se rešim roke njegove.',
        2: 'David torej vstane in gre na ono stran, on in šeststo mož, ki so bili ž njim, k Ahisu, sinu Maokovemu, kralju v Gatu.',
        3: 'In David je prebival z Ahisom v Gatu, on in možje njegovi, vsak z družino svojo, tudi David z dvema ženama svojima, z Ahinoamo Jezreelsko in Abigailo Karmelsko, bivšo Nabalovo ženo.',
        4: 'In ko so povedali Savlu, da je David pobegnil v Gat, ga ni več iskal.',
        5: 'In David reče Ahisu: Ako sem, prosim, našel milost v očeh tvojih, naj mi dado prostora v kakem mestu na deželi, da bi v njem prebival; kajti čemu naj prebiva hlapec tvoj pri tebi v kraljevem mestu?',
        6: 'Tedaj mu da Ahis Ziklag tisti dan. Odtod je Ziklag last kraljev Judovih do tega dne.',
        7: 'In število dni, kar jih je David prebil v deželi Filistejcev, je bilo leto in štiri mesece.',
        8: 'David pa in možje njegovi so hodili gori in so naskakovali Gesurske in Girzejce in Amalekovce, zakaj ti so bili prebivalci te dežele od starodavna, do tja, koder se gre v Sur in do Egiptovske dežele.',
        9: 'In David je pustošil deželo ter ni dal živeti ne možu, ne ženi, in ko je bil pobral ovce, goveda, osle, velblode in oblačila, se je vrnil in prišel k Ahisu.',
        10: 'In ko je Ahis vprašal: Kam ste vdrli danes? je rekel David: V južno stran Judovo, in v južno stran Jerahmelijcev, in v južno stran Kenejcev.',
        11: 'David pa ni ohranil živega ne moža, ne žene, da bi ju pripeljal v Gat, rekoč: Da bi nas ne ovadili in ne rekli: Tako je storil David! Tako je navadno delal, dokler je prebival v deželi Filistejcev.',
        12: 'Zato je Ahis veroval Davidu in menil: Omrzil se je pri ljudstvu svojem Izraelu, zato bode hlapec moj vekomaj.',
    },
    28: {
        1: 'Zgodi se pa v tem času, da skličejo Filistejci bojne trume svoje na vojsko, da se bojujejo z Izraelom. In Ahis veli Davidu: Vedi za gotovo, da pojdeš z mano na vojsko, ti in moštvo tvoje.',
        2: 'In David reče Ahisu: Potem tudi zveš, kaj stori hlapec tvoj. Ahis pa reče Davidu: Zato te postavim za varuha glave svoje vse svoje žive dni.',
        3: 'Samuel pa je bil umrl, in ves Iz rael je žaloval po njem. In pokopali so ga v Rami, v mestu njegovem. Savel pa je bil odpravil iz dežele rotilce mrtvih in vražarje.',
        4: 'Ko se torej zbero Filistejci ter pridejo in se utabore v Sunemu, zbere tudi Savel vse Izraelce, in utabore se na Gilboi.',
        5: 'In ko vidi Savel tabor Filistejcev, se zboji in srce mu obupa.',
        6: 'In Savel je vprašal za svet Gospoda, a Gospod mu ni odgovoril ne po sanjah, ne po Urimu, ne po prorokih.',
        7: 'Tedaj veli Savel hlapcem svojim: Poiščite mi ženo, ki se peča z rotenjem mrtvih, da bi šel k njej in jo vprašal. In hlapci njegovi mu reko: Glej, v Endoru je žena, ki je rotilka mrtvih.',
        8: 'In Savel se preobleče za drugo osebo in gre tja, in dva moža ž njim; in pridejo po noči k ženi. In on reče: Vedežuj mi, prosim, po duhu mrtvega in pripelji mi gori, kogar ti bom imenoval.',
        9: 'In žena mu reče: Glej, ti veš, kar je storil Savel, kako je potrebil iz dežele rotilce duhov in vražarje; zakal pa nastavljaš zanko duši moji, da me spraviš v smrt?',
        10: 'In Savel ji priseže pri Gospodu, rekoč: Kakor res Gospod živi, za to te ne zadene nobena kazen!',
        11: 'Nato vpraša žena: Koga naj ti pripeljem gori? On reče: Pripelji mi Samuela!',
        12: 'In ko žena zagleda Samuela, zavpije z močnim glasom, in reče Savlu: Zakaj si me prekanil? ker ti si Savel!',
        13: 'In kralj ji reče: Ne boj se! Kaj vidiš? Žena odgovori Savlu: Vidim boga stopati gori iz zemlje.',
        14: 'On jo vpraša: Kakšna je njegova podoba? Ona reče: Star mož prihaja gori, ogrnjen s plaščem. In Savel zazna, da je Samuel, in se skloni z obličjem k tlom in stori poklon.',
        15: 'In Samuel reče Savlu: Zakaj me vznemirjaš s tem, da me kličeš gori? In Savel odgovori: V stiski sem veliki, kajti Filistejci se vojskujejo z menoj, in Bog me je zapustil in mi ne odgovarja več, ne po prorokih, ne po sanjah; zato sem dal poklicati tebe, da mi oznaniš, kaj naj storim.',
        16: 'Samuel reče: Čemu pa vprašuješ mene, ker te je Gospod zapustil in je postal tvoj nasprotnik?',
        17: 'In Gospod je storil zase, kakor je po meni govoril, in Gospod je odtrgal kraljestvo iz roke tvoje in ga je dal bližnjiku tvojemu, Davidu.',
        18: 'Ker nisi poslušal glasu Gospodovega in nisi izvršil silne jeze njegove nad Amalekom, zato ti je takole storil Gospod sedaj.',
        19: 'Vrhutega bo dal Gospod Izraela s teboj vred v roko Filistejcem, in jutri bodeš ti in sinovi tvoji pri meni; tudi vojsko Izraelovo da Gospod Filistejcem v roke.',
        20: 'Tedaj pade Savel naglo na tla, kakor je bil dolg, kajti silno se je prestrašil zaradi Samuelovih besed, in ni bilo nič moči več v njem, zakaj zaužil ni kruha cel dan in celo noč.',
        21: 'In tista žena pristopi k Savlu in, videč, da je zelo preplašen, mu reče: Glej, dekla tvoja je poslušala glas tvoj, in izpostavila sem nevarnosti življenje svoje, poslušajoč besede tvoje, ki si mi jih govoril.',
        22: 'Sedaj pa poslušaj tudi ti, prosim, dekle svoje glas: predložim ti grižljaj kruha, in jej, da si opomoreš, ko pojdeš svojo pot.',
        23: 'On pa se brani in reče: Nočem jesti. Ali hlapca njegova s tisto ženo vred ga silita, in poslušal je njih glas. In vstane s tal in sede na posteljo.',
        24: 'Žena pa je imela v hiši pitano tele, in hitro ga zakolje, in vzame moke in jo zamesi in speče opresnike.',
        25: 'Potem prinese pred Savla in njegova hlapca, in jedli so. Nato vstanejo in odidejo še tisto noč.',
    },
    29: {
        1: 'Filistejci pa so zbrali vse vojne trume svoje v Afeku; in Izrael se je utaboril ob studencu, ki je v Jezreelu.',
        2: 'In knezi Filistejcev so šli pri sto in tisočih svojih, a David in možje njegovi so šli v zadnjem voju z Ahisom.',
        3: 'Tedaj reko knezi Filistejcev: Kaj hočejo tu ti Hebrejci? In Ahis reče knezom Filistejcev: Ali ta ni David, hlapec Savla, izraelskega kralja, ki je bil pri meni že mnogo dni ali let, in nisem ničesar našel na njem, odkar je uskočil k meni do tega dne?',
        4: 'Ali knezi Filistejcev se razsrde nanj in mu reko: Véli, da se vrne ta mož, da gre nazaj v mesto svoje, kamor si ga postavil, nikar naj ne hodi z nami doli v boj, da nam ne postane v bitki nasprotnik; kajti s čim bi si pridobil blagovoljnost gospoda svojega kakor z glavami teh mož?',
        5: 'Ali ta ni David, o katerem so plešoč pele druga drugi, govoreč: Savel je pobil svoj tisoč, a David svojih deset tisoč?',
        6: 'Tedaj pokliče Ahis Davida in mu reče: Kakor res Gospod živi, pošten si, in všeč bi mi bilo, da hodiš z menoj ven in noter v vojski, zakaj nisem nič hudega našel na tebi, odkar si prišel k meni do tega dne; ali knezom nisi po volji.',
        7: 'Zato se zdaj vrni in pojdi v miru, da ne storiš, kar bi se videlo hudo filistejskim knezom.',
        8: 'David pa reče Ahisu: Kaj pa sem storil, ali kaj si našel na hlapcu svojem, dokler sem bil pred obličjem tvojim do tega dne, da ne smem iti in se bojevati zoper sovražnike gospoda svojega, kralja?',
        9: 'Ahis odgovori in reče Davidu: Vem, da si dober v mojih očeh kakor angel Božji; ali Filistejcev knezi so dejali: Naj ne gre ta z nami v boj!',
        10: 'Zatorej vstani zgodaj zjutraj s hlapci gospoda svojega, ki so prišli s teboj. In ko zjutraj, kakor hitro se zdani, vstanete, kar odrinite!',
        11: 'Tedaj vstane zgodaj David in možje njegovi, da odidejo zarana in se vrnejo v deželo Filistejcev. Filistejci pa so šli gori v Jezreel.',
    },
    30: {
        1: 'Ko pa pride David z možmi svojimi tretji dan proti Ziklagu, so bili Amalekovci naskočili južno stran in Ziklag, in so udarili v Ziklag in ga požgali;',
        2: 'in so ujeli žene in vse, kar jih je bilo v njem, male in velike: niso sicer nikogar ubili, a odgnali so jih in šli svojo pot.',
        3: 'Ko torej pridejo David in možje njegovi k mestu, vidijo, da je požgano z ognjem, in njih žene in njih sinovi in hčere so odpeljani v sužnost.',
        4: 'Tedaj David in ljudstvo, ki je bilo ž njim, povzdigne glas svoj, in jočejo toliko, da niso mogli več jokati:',
        5: 'Tudi obe ženi Davidovi sta bili ujeti, Ahinoama Jezreelska in Abigaila, bivša žena Nabala Karmelskega.',
        6: 'In David je bil v veliki stiski, zakaj ljudstvo se je dogovarjalo, da ga posujejo s kamenjem, ker je bilo vse ljudstvo v srcu užaljeno, vsak nad sinovi in hčerami svojimi. Ali David se ohrabri v Gospodu, Bogu svojem.',
        7: 'In David veli Abiatarju duhovniku, sinu Ahimelekovemu: Prosim, prinesi mi sem naramnik! In Abiatar prinese tja naramnik k Davidu.',
        8: 'In David vpraša Gospoda, rekoč: Ali naj udarim za tisto roparsko druhaljo? Jih li dohitim? On mu odgovori: Spusti se za njimi, zakaj gotovo jih dohitiš in izvršiš popolno rešitev!',
        9: 'David torej odrine, on in šeststo mož, ki so bili pri njem. In ko pridejo k potoku Besorju, jih nekaj obstane ondi.',
        10: 'Ali David in štiristo mož se žene dalje; kajti dvesto jih je zaostalo, ker so bili tako upehani, da niso mogli iti čez potok Besor.',
        11: 'In najdejo Egipčana na polju ter ga pripeljejo k Davidu, in mu dado kruha, in je jedel, in ga napojé z vodo,',
        12: 'in mu dado kepo smokev in dve gruči posušenega grozdja: in ko se naje, se poživi, kajti ni jedel kruha, ne pil vode tri dni in tri noči.',
        13: 'In David mu reče: Čigav si in odkod si? Odgovori: Mladenič iz Egipta sem, nekega Amalekovca hlapec, in gospodar moj me je zapustil, ker sem bil bolan pred tremi dnevi.',
        14: 'Naskočili smo južno stran Keretejcev in Judovo in južno stran Kalebovo, in Ziklag smo požgali z ognjem.',
        15: 'In David mu reče: Me li hočeš doli peljati k tej druhali? On reče: Prisezi mi pri Bogu, da me ne umoriš in tudi ne izročiš gospodarja mojega rokam, in popeljem te doli k tej druhali.',
        16: 'Peljal ga je torej doli; in glej, bili so razkropljeni po vsem tistem kraju in so jedli in pili in praznovali zaradi vsega velikega ropa, ki so ga bili vzeli iz Filistejcev dežele in iz dežele Judove.',
        17: 'In David jih je pobijal od somraka do večera drugega dne, in nihče se ni rešil, samo štiristo mladeničev, ki so na velblodih pobegnili.',
        18: 'In David je otel vse, kar so bili vzeli Amalekovci; tudi dve ženi svoji je osvobodil David.',
        19: 'Nič se ni pogrešalo, ne malo, ne veliko, ne sinovi, ne hčere, prav nič, kar so jim bili poplenili: vse je David zopet dobil.',
        20: 'In David je vzel vso drobnico in goved, in gnali so jo pred drugo živino in pravili: To je plen Davidov!',
        21: 'In David dospe k tistim dvesto možem, ki so bili tako upehani, da niso mogli iti za Davidom, zato so jim veleli ostati pri potoku Besorju; ti pridejo Davidu naproti in ljudstvu, ki je bilo ž njim. In ko pristopi David k ljudstvu, jih pozdravi prijazno.',
        22: 'Tedaj izpregovore vsi hudobni in Belijalovi možje med temi, ki so bili šli z Davidom, in reko: Ker niso šli z nami, ne dajmo jim nič plena, ki smo ga oteli; samo naj vzame sleherni svojo ženo in otroke svoje, pa naj odidejo!',
        23: 'Nato veli David: Ne ravnajte tako, bratje moji, s tem, kar nam je dal Gospod, ki nas je obvaroval in nam dal v roke roparsko druhal, ki je bila prišla zoper nas.',
        24: 'In kdo bi vas v tem poslušal? Marveč kakršen je del tistega, ki je šel v boj, takšen bodi del tega, ki je ostal pri prtljagi: po enako naj si razdelijo.',
        25: 'In tako je bilo od tega časa in poslej, da je to ustanovil kot postavo in pravilo v Izraelu, do tega dne.',
        26: 'In ko je David prišel v Ziklag, pošlje od plena starejšinam Judovim, prijateljem svojim, rekoč: Glejte, to vam je blagodar od plena sovražnikov Gospodovih.',
        27: 'Namreč tem v Betelu in tem, ki so bili v Ramotu na jugu, in tem v Jatirju',
        28: 'in tem v Aroerju in tem v Sifmotu in tem v Estemoi',
        29: 'in tem v Rahalu in tem, ki so bili v mestih Jerahmelijcev in v mestih Kenejcev,',
        30: 'in tem v Hormi in tem v Korašanu in v Atahu,',
        31: 'in tem v Hebronu in v vseh mestih, v katera je kdaj zahajal David in možje njegovi.',
    },
    31: {
        1: 'Filistejci pa so se bojevali z Izraelom, in Izrael je zbežal pred Filistejci, in so padali pobiti na gorovju Gilboi.',
        2: 'In Filistejci so bili trdo za petami Savlu in sinovom njegovim, in pobili so Jonatana in Abinadaba in Malhisua, sinove Savlove.',
        3: 'In bitka je hudo pritiskala na Savla, in lokostrelci so ga dohiteli, in v strahu je trepetal pred strelci.',
        4: 'Tedaj reče Savel svojemu oprodi: Izderi meč svoj in me prebodi, da ne pridejo ti neobrezanci in me ne prebodejo ter si smeh napravijo z menoj. Ali njegov oproda ni hotel, ker se je silno bal. Zato vzame Savel meč svoj in se nasadi nanj.',
        5: 'Ko pa vidi njegov oproda, da je Savel mrtev, nasadi se tudi on na svoj meč in umre ž njim.',
        6: 'Tako je umrl Savel in trije sinovi njegovi in oproda njegov in možje njegovi, vsi skupaj tisti dan.',
        7: 'Ko pa vidijo možje Izraelovi, ki so bili onostran doline in ki so bili za Jordanom, da bežé možje Izraelovi ter da so Savel in sinovi njegovi mrtvi, zapuste mesta svoja, pa pobegnejo. In Filistejci pridejo in se nastanijo po njih.',
        8: 'In drugi dan pridejo Filistejci, da slečejo pobite, in najdejo Savla in tri sinove njegove, ležeče na gorovju Gilboi.',
        9: 'In mu odsekajo glavo in snamejo z njega orožje njegovo, in pošljejo po deželi Filistejcev naokrog, da se ta vesela vest oznani v hiši njih malikov in med ljudstvom.',
        10: 'In orožje njegovo razpolože v hiši Astartini, truplo njegovo pa obesijo na zid v Betsanu.',
        11: 'Ko pa slišijo prebivalci v Jabesu v Gileadu, kaj so storili Filistejci Savlu,',
        12: 'se vzdignejo, kar jih je bilo vojščakov, in gredo vso noč in snamejo truplo Savlovo in trupla sinov njegovih z zida v Betsanu, ter jih prineso v Jabes in jih ondi sežgo.',
        13: 'In vzamejo njih kosti in jih pokopljejo pod tamarisko v Jabesu in se postijo sedem dni.',
    },
}
